-- docs/task-triplets-migration.sql
-- Generated by scripts/generate-triplet-seed.py. Do not hand-edit.
-- Run AFTER docs/competency-framework-migration.sql. Idempotent.
--
-- The Learning Objective -> Task -> Assessment Criterion triplets, the
-- pedagogical unit the internship content document is built on. Read-only:
-- an advisor derives tasks from these but never edits them.
--
-- 480 rows across 48 KPIs.

CREATE TABLE IF NOT EXISTS kpi_triplets (
  id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  kpi_id        UUID NOT NULL REFERENCES competency_kpis(id) ON DELETE CASCADE,
  triplet_index INT  NOT NULL,
  objective     TEXT NOT NULL,
  task          TEXT NOT NULL,
  criterion     TEXT NOT NULL,
  UNIQUE (kpi_id, triplet_index)
);

ALTER TABLE kpi_triplets ENABLE ROW LEVEL SECURITY;

-- Reference data, like the framework itself: a SELECT policy and no write
-- policy at all. This is a project deliverable, not app state.
DROP POLICY IF EXISTS "kpi triplets read" ON kpi_triplets;
CREATE POLICY "kpi triplets read" ON kpi_triplets
  FOR SELECT TO authenticated USING (true);

INSERT INTO kpi_triplets (kpi_id, triplet_index, objective, task, criterion)
SELECT k.id, v.triplet_index, v.objective, v.task, v.criterion
FROM (VALUES
  ('teamwork', 1, 1, 1, 'Comprehend the overall project organizational structure.', 'Map out the project team''s organizational chart using internal directories and create a block diagram in word and upload in the app.', 'Accurately diagrams the reporting structure and distinct roles involved in the current project.'),
  ('teamwork', 1, 1, 2, 'Recognize the specific duties of core technical or execution roles.', 'Shadow a technical team member for a designated block of time and document their daily workflow. Write a one-page report with designation, roles and responsibilities and challenges faced within that period and upload in App.', 'Lists key technical responsibilities and correctly explains their direct impact on project deliverables.'),
  ('teamwork', 1, 1, 3, 'Identify the function and impact of Project Management.', 'Review a current project timeline and resource allocation sheet with a Project Manager. Write a one-page report on the project, its timeline and whether sufficient resources are allotted and upload in app.', 'Clearly explains how the Project Manager coordinates tasks and resolves bottlenecks across different departments.'),
  ('teamwork', 1, 1, 4, 'Understand cross- functional dependencies within the team.', 'Actively participate in a cross- functional stand-up or status meeting and take observational notes. Participate in two cross- functionality meeting and write a one-page report on discussion in the meeting and upload in app.', 'Identifies and documents at least three clear dependencies between different professional roles discussed in the meeting.'),
  ('teamwork', 1, 1, 5, 'Comprehend the role of Quality Assurance (QA) or compliance functions.', 'Review recent testing reports or quality audits alongside a QA specialist. Write the feedback from the QA specialist and upload in a App.', 'Describes how QA feedback specifically alters or guides the workflow of the design or development roles.'),
  ('teamwork', 1, 1, 6, 'Recognize the influence of client- facing or stakeholder management roles.', 'Read the initial project brief or statement of work provided by the account management team. Write a small note on the influence of the role and upload it in app.', 'Explains how the requirements gathered by client-facing roles dictate the constraints and goals for the execution team.'),
  ('teamwork', 1, 1, 7, 'Understand the integration of specialized support roles (e.g., IT Support, HR, Legal).', 'Conduct a brief informational interview with a support staff member assigned to the project. Write the duties carried out by specialised support roles and upload it in App.', 'Summarizes how the specialized support role enables the core project team to function efficiently and safely.'),
  ('teamwork', 1, 1, 8, 'Analyse how different professions approach problem- solving.', 'Attend a project post-mortem, retrospective, or troubleshooting session. Write a report on the problem and solving method used and upload in the App.', 'Documents how at least two different roles approached a specific project challenge from their unique professional viewpoints.'),
  ('teamwork', 1, 1, 9, 'Differentiate the communication priorities of various roles.', 'Analyse a shared project communication channel or an extensive email thread. Analyse and email thread and write the conveyed idea in each email and upload in a App.', 'Identifies clear variations in communication focus among different roles.'),
  ('teamwork', 1, 1, 10, 'Synthesize individual role contributions into a cohesive whole.', 'Prepare a summary presentation outlining "Who does what" for an upcoming project phase. Write the individual name and responsibilities and upload it in App.', 'Successfully presents the summary to a supervisor, accurately detailing the interconnected contributions of at least four distinct roles.'),
  ('teamwork', 1, 2, 1, 'Comprehend the organization''s specific Diversity and Inclusion (D&I) policies.', 'Review the employee handbook, corporate D&I guidelines, and complete mandatory D&I onboarding modules. Write down top three important points and upload in the app.', 'Successfully completes onboarding assessments and accurately summarizes key workplace behavioural expectations to the supervisor.'),
  ('teamwork', 1, 2, 2, 'Demonstrate active listening in collaborative settings.', 'Participate in group meetings by allowing colleagues to finish speaking without interruption and acknowledging their points. Get feedback from the member of the meeting and upload the same to the App.', 'Supervisor and peer feedback indicates the intern consistently listens attentively and does not talk over others.'),
  ('teamwork', 1, 2, 3, 'Utilize inclusive language in professional communication.', 'Draft internal team emails, project documentation, and chat messages using neutral, professional, and inclusive terminology. Five emails written by the candidate shall be uploaded in App.', 'Written communications are routinely reviewed and found to be free of exclusionary, biased, or culturally insensitive language.'),
  ('teamwork', 1, 2, 4, 'Respect differing working styles and professional backgrounds.', 'Partner with a colleague from a different department or background to complete a shared project milestone. Write a note on the new ways learned from the colleague through the project.', 'Receives positive feedback from the collaborative partner regarding the intern''s adaptability, patience, and openness to alternative methods.'),
  ('teamwork', 1, 2, 5, 'Value all team contributions equally, regardless of hierarchy.', 'Co-facilitate a brainstorming session or team discussion, actively inviting input from quieter or junior members. Get feedback from the team member present on the meeting and upload in App.', 'Successfully elicits and respectfully documents input from all meeting attendees, ensuring no single voice dominates the session.'),
  ('teamwork', 1, 2, 6, 'Identify and avoid workplace microaggressions.', 'Review provided internal training materials, webinars, or articles on workplace sensitivity and unconscious bias. Write three important points and upload in App.', 'Can accurately identify examples of non-inclusive behaviour in hypothetical scenarios and articulate strategies to maintain a respectful environment.'),
  ('teamwork', 1, 2, 7, 'Navigate professional disagreements with tact and respect.', 'Engage in a project design or strategy review, ensuring all critiques are focused strictly on the work/ideas and not the individual. Analyse a similar scenario and include your thoughts on how it can be approached and upload it in App.', 'Maintains a calm, objective tone during debates and reaches compromises without escalating to personal conflict.'),
  ('teamwork', 1, 2, 8, 'Respect colleagues'' time, schedules, and professional boundaries.', 'Organize project check-ins using shared calendars, strictly observing colleagues'' working hours, time zones, and "focus time" blocks. Write a note on the experience of organising a meeting with colleagues and upload it in App.', '100% of meetings scheduled by the intern respect calendar availability and begin/end precisely on time.'),
  ('teamwork', 1, 2, 9, 'Support accessibility standards in shared workspaces and outputs.', 'Create or format shared team documents and presentations ensuring basic accessibility. Upload the presentation in App', 'Materials submitted by the intern pass a baseline accessibility check and can be easily utilized by all team members.'),
  ('teamwork', 1, 2, 10, 'Contribute to a psychologically safe and welcoming team culture.', 'Actively participate in team-building activities, check-ins, or introductions, extending a welcoming demeanour to all peers. Take feedback from team members about the participation and upload in App', 'End-of-rotation peer evaluations specifically highlight the intern''s approachable demeanour and positive contribution to team morale.'),
  ('teamwork', 2, 1, 1, 'Comprehend the specific requirements and parameters of an assigned task.', 'Review the assignment brief and ask clarifying questions to the supervisor. Write a small note on the assignment and upload in App', 'Can accurately restate the task goals, required deliverables, and deadlines back to the supervisor.'),
  ('teamwork', 2, 1, 2, 'Manage individual time effectively to meet shared project deadlines.', 'Create a personal timeline or checklist to track daily progress on the assigned project. Write down the check list on the App', 'Consistently submits interim drafts or status updates according to the schedule agreed upon with the supervisor.'),
  ('teamwork', 2, 1, 3, 'Execute tasks according to established team standards.', 'Follow a specific standard operating procedure to complete a task. Write the steps of execution and upload in the App', 'The final output adheres strictly to provided technical or formatting guidelines, requiring minimal structural corrections.'),
  ('teamwork', 2, 1, 4, 'Communicate roadblocks proactively to leadership.', 'Identify when a task is stalled due to missing information or technical issues and immediately notify the supervisor. Involve in a project and note down the roadblock faced and upload in App.', 'Escalates issues promptly rather than hiding delays, providing a clear summary of what is needed to proceed.'),
  ('teamwork', 2, 1, 5, 'Perform basic quality control on individual deliverables.', 'Conduct a self-review of the completed portion before submitting it for review. Write a note about the self-review and upload it in the App', 'Submitted work demonstrates high attention to detail and accurately addresses all baseline requirements outlined in the initial brief.'),
  ('teamwork', 2, 1, 6, 'Navigate project hand-offs and shared workspaces.', 'Upload, format, or merge the completed assigned portion into the team''s designated drive. Upload the screen shot in the App.', 'Files and deliverables are correctly named, properly organized, and easily accessible to the rest of the team.'),
  ('teamwork', 2, 1, 7, 'Receive and implement constructive feedback effectively.', 'Review the supervisors redlines or feedback on an initial draft and execute the requested revisions. Write note on the understanding of feedback from supervisor and upload it in App.', 'The second iteration of the work accurately incorporates all supervisory feedback without needing repeated corrections on the same issues.'),
  ('teamwork', 2, 1, 8, 'Understand the impact of individual delays on team dependencies.', 'Map out how their specific assigned task feeds into the next phase of a colleague''s workflow. Create a chart with input and output from each team and upload it in App.', 'Accurately identifies which team member is waiting on their deliverable and explains why timely completion is critical to the broader project.'),
  ('teamwork', 2, 1, 9, 'Demonstrate reliability in meeting final delivery expectations.', 'Commit to and deliver the finalized portion of a collaborative project phase by the deadline. Write the experience about the final deliverable (challenges faced and overcame) and upload in App', 'Delivers the completed, review-ready task on or before the deadline 100% of the time or negotiates an extension with the supervisor well in advance.'),
  ('teamwork', 2, 1, 10, 'Close out tasks using proper reporting protocols.', 'Formally conclude the assignment by updating the status in the project tracker and notifying relevant stakeholders. Upload the Screenshot of the tracker and email notification in the App.', 'tools reflect the accurate "completed" status, and the supervisor is explicitly notified that the hand-off is ready.'),
  ('teamwork', 2, 2, 1, 'Accurately assess the completion and quality of primary assignments.', 'Complete a self-review of assigned deliverables and obtain supervisor sign-off before seeking additional work. Write a note about review and upload in App', 'Supervisor confirms that the intern''s primary tasks are 100% complete and meet quality standards before the intern initiates help elsewhere.'),
  ('teamwork', 2, 2, 2, 'Develop situational awareness regarding the team''s overall workload.', 'Review the team''s project management board (e.g., Kanban, Jira) daily to identify backlogged items or colleagues with heavy task loads. Write a note on the backlog and overload team member for the particular week and upload in App', 'Can accurately point out at least two areas where the team is currently facing resource constraints or approaching tight deadlines.'),
  ('teamwork', 2, 2, 3, 'Proactively communicate availability to the team.', 'Send a concise, professional message to the team channel or supervisor stating current availability and offering specific support. Upload the screenshot of the message and upload in App', 'Communications offering help are timely, polite, and clearly state the intern''s current capacity without sounding demanding.'),
  ('teamwork', 2, 2, 4, 'Assess personal capabilities to offer relevant assistance.', 'Match personal skills to the specific needs of a struggling team member. Write note about the personal skill present, how it was used and upload in App', 'Offers help on tasks where they possess the necessary baseline competence, avoiding taking on highly specialized tasks beyond their current capability.'),
  ('teamwork', 2, 2, 5, 'Clarify the scope and expectations of secondary tasks.', 'Conduct a brief alignment check with the colleague receiving help to understand the exact requirements and deadline of the delegated work. Write a note about the goal, timeframe and expected output and upload in App.', 'Can accurately summarize the goal, timeframe, and expected output format of the assisting task before initiating the work.'),
  ('teamwork', 2, 2, 6, 'Adapt to colleagues'' preferred workflows and tools.', 'Complete a support task utilizing the specific file structures, naming conventions, or software preferred by the colleague being helped. Get a feedback from the colleague about the integration into the project and upload in App.', 'The assisted colleague reports that the intern seamlessly integrated into their process without causing disruption or requiring excessive handholding.'),
  ('teamwork', 2, 2, 7, 'Differentiate and track time spent on support tasks.', 'Log time spent assisting others separately from primary tasks in the team''s time-tracking software or daily report. Take a screenshot of the time log spent on support activities and upload in App', 'Time logs show a clear, accurate distinction between core duties and support duties.'),
  ('teamwork', 2, 2, 8, 'Provide support with a constructive and positive demeanour.', 'Assist a peer with a repetitive, foundational, or menial task to help them meet a critical project milestone. Collect feedback from peers and upload in App', 'Peer feedback highlights the intern''s willingness to help with foundational tasks without complaint and with a collaborative attitude.'),
  ('teamwork', 2, 2, 9, 'Recognize professional boundaries and focus time.', 'Observe colleagues'' status indicators and refrain from interrupting deep focus work to offer help. Collect feedback from colleague about the assistance offered and upload in App.', 'Consistently respects colleagues'' focus time and only offers assistance during appropriate break points, open communication windows, or via asynchronous channels.'),
  ('teamwork', 2, 2, 10, 'Document shared efforts for seamless hand- backs.', 'Write a brief handover summary or leave clear comments detailing the steps taken and progress made on the assisted task. Upload the summary in App.', 'The primary task owner can immediately resume the work based on the clarity and completeness of the intern''s documentation and handover notes.'),
  ('teamwork', 3, 1, 1, 'Demonstrate openness and active listening when receiving peer feedback.', 'Participate in a peer-review session or 1-on-1 critique of a draft, taking detailed notes without interrupting the reviewer. Collect feedback from peers about the active listening and upload in App', 'Supervisor or peer confirms the intern listened attentively, asked clarifying questions, and did not exhibit defensive behaviour.'),
  ('teamwork', 3, 1, 2, 'Accurately interpret and document provided feedback.', 'Restate or summarize the verbal feedback received in a follow-up email or comment thread to ensure total alignment. Upload the summarised verbal feedback in App', 'The written summary accurately reflects the reviewer''s original intent without omitting or misinterpreting critical points.'),
  ('teamwork', 3, 1, 3, 'Differentiate between mandatory corrections and subjective suggestions.', 'Review a list of peer comments and categorize them into "required technical fixes" versus "stylistic recommendations." Upload the categorised comments in the App', 'Accurately prioritizes the feedback, ensuring all factual, structural, or compliance errors are marked as mandatory fixes.'),
  ('teamwork', 3, 1, 4, 'Translate vague feedback into actionable steps.', 'Identify an ambiguous comment and ask the reviewer targeted questions to define exactly what needs changing. Note the ambiguous comment and write down the explanation provided by the colleague and upload in App', 'Successfully turns a general critique into a concrete, executable task through professional and polite follow-up communication.'),
  ('teamwork', 3, 1, 5, 'Execute specific technical or formatting revisions accurately.', 'Revise a submitted draft, calculation, or code snippet to directly incorporate the specific redlines provided by a senior team member. Get feedback about the draft and upload in App.', 'The subsequent version of the work product includes 100% of the agreed-upon corrections, accurately executed.'),
  ('teamwork', 3, 1, 6, 'Resolve conflicting feedback from multiple stakeholders.', 'Identify contradictory comments from two different team members on a shared document and facilitate a brief alignment chat to find a resolution. In a document include both the comments and explain the conflicts and resolution and upload in App.', 'Successfully navigates the conflict with tact, producing a final output that satisfies the core project requirements of both parties.'),
  ('teamwork', 3, 1, 7, 'Utilize version control and change tracking effectively.', 'Implement requested revisions using "Track Changes," version control commit messages, or by maintaining a clear change log. Upload Screen shot of the log in the App.', 'The change log or tracked document clearly and explicitly maps the executed revisions back to the specific feedback received.'),
  ('teamwork', 3, 1, 8, 'Verify the successful integration of feedback (Closing the Loop).', 'Resubmit the revised work to the original reviewer, explicitly highlighting where and how their concerns were addressed. Take a note of the concerns and solution and upload in App.', 'The reviewer signs off on the revised deliverable without needing to repeat or re-explain their initial feedback.'),
  ('teamwork', 3, 1, 9, 'Generalize feedback to prevent repeating past mistakes.', 'Create a personal "quality assurance checklist" based on previous feedback and use it to self-review a brand-new assignment. Create the checklist and note the feedback based on the checklist and upload in App.', 'The new assignment demonstrates that the intern has internalized past lessons, entirely avoiding the errors corrected in previous review cycles.'),
  ('teamwork', 3, 1, 10, 'Maintain a professional and appreciative demeanour throughout the review cycle.', 'Thank the reviewer for their time and constructive insights once the final deliverable is approved. Take screen shot of the replies and upload in App.', 'Consistently demonstrates professionalism and gratitude, visibly treating the feedback loop as a collaborative growth opportunity rather than a personal critique.'),
  ('teamwork', 3, 2, 1, 'Differentiate between credible, high-value resources and general noise.', 'Curate a short list of industry articles, software tools, or tutorials that are highly relevant to the team''s current project phase. Note the list a document and upload in App.', 'Supervisor confirms the selected resources are accurate, up-to-date, and from reputable, industry- standard sources.'),
  ('teamwork', 3, 2, 2, 'Identify knowledge gaps or technical bottlenecks within the team.', 'Monitor team discussions or stand-up meetings to pinpoint recurring questions or workflow inefficiencies. Take a note of the workflow inefficiencies, recurring questions and upload in App.', 'Accurately identifies at least one specific technical area where the team could directly benefit from supplementary information.'),
  ('teamwork', 3, 2, 3, 'Utilize appropriate internal communication channels for knowledge sharing.', 'Post a relevant technical insight or resource link in the team''s designated knowledge-sharing forum. Take a screenshot of the post and upload in App.', 'The resource is shared in the correct, centralized forum rather than being lost in direct messages or fragmented emails.'),
  ('teamwork', 3, 2, 4, 'Provide clear context and actionable takeaways for shared information.', 'Write a brief, scannable summary accompanying a shared link, explicitly explaining why it is useful and how it applies to the project. Upload the summary in App', 'Colleagues can instantly understand the relevance and value of the resource from the summary without having to read the entire source first.'),
  ('teamwork', 3, 2, 5, 'Translate personal problem-solving breakthroughs into shared knowledge.', 'Write a brief "how-to" snippet or mini-SOP after successfully navigating a new technical challenge or software quirk. Upload the same in App.', 'The written snippet is clear, easily reproducible by peers, and successfully added to the team''s shared documentation repository.'),
  ('teamwork', 3, 2, 6, 'Articulate technical insights verbally in an accessible manner.', 'Prepare and deliver a brief informal demo showing a newly discovered software shortcut, technique, or best practice. Photos or videos of the demo to be uploaded in App.', 'The presentation is concise, avoids unnecessary jargon, and peers confirm they learned a usable new skill.'),
  ('teamwork', 3, 2, 7, 'Update and maintain the accuracy of existing team knowledge bases.', 'Proactively review an existing shared team document, identify an outdated process or broken link, and update it with current information. Write e note about the damage and repair and upload in App.', 'The updated document is technically sound, functional, and the intern successfully notifies the team of the revision.'),
  ('teamwork', 3, 2, 8, 'Tailor insights to the specific needs of different roles.', 'Direct a highly specialized technical article or tool directly to a specific colleague whose role aligns perfectly with the content. Create the combination and provide explanation of the suitability and upload in App.', 'The recipient confirms the shared resource is highly relevant and immediately applicable to their specific tasks.'),
  ('teamwork', 3, 2, 9, 'Foster a reciprocal knowledge-sharing environment.', 'Ask a targeted, open-ended question in a team forum requesting peers to share their favourite approaches or tools for a specific task. Take a screen shot of the questions and response and upload in App.', 'Successfully initiates a constructive technical discussion that prompts at least two other colleagues to share their own insights.'),
  ('teamwork', 3, 2, 10, 'Establish a consistent habit of continuous sharing.', 'Commit to sharing at least one highly relevant technical insight, workflow improvement, or resource per project phase or sprint. Write a note on the suggestions provided and explanations and upload in App.', 'End-of-rotation evaluations indicate the intern established a reliable pattern of contribution, rather than treating knowledge sharing as a one-off event.'),
  ('teamwork', 4, 1, 1, 'Identify the objective root cause of a technical or interpersonal disagreement.', 'Observe a minor team disagreement and write down the core conflicting points objectively. Take a note of the conflicting point and reason for disagreement and ways to resolve it and upload in App.', 'Accurately isolates the core issue (e.g., conflicting requirements, missing data) without assigning personal blame or bias.'),
  ('teamwork', 4, 1, 2, 'Apply active de- escalation techniques during tense discussions.', 'Intervene in a stalling technical debate by suggesting a brief pause or restating the shared project goal. Feedback from a member of the meeting shall be collected and upload in App.', 'Successfully lowers the emotional temperature of the discussion, refocusing the team on the objective deliverable.'),
  ('teamwork', 4, 1, 3, 'Utilize authoritative project documentation to resolve technical ambiguities.', 'Retrieve the original project brief, SOP, or technical manual to clarify a disputed requirement during a meeting. Write a note about the experience of solving it and upload in App.', 'Resolves the misalignment quickly by referencing factual, approved documentation rather than relying on opinions.'),
  ('teamwork', 4, 1, 4, 'Validate differing perspectives to foster a collaborative resolution environment.', 'Verbally summarize each party''s viewpoint during a disagreement before suggesting a path forward. Write a note on the summary and upload in App.', 'Both conflicting parties explicitly confirm the intern accurately and fairly represented their individual perspectives.'),
  ('teamwork', 4, 1, 5, 'Propose actionable compromises for conflicting technical approaches.', 'Draft a hybrid solution or middle- ground proposal when two peers disagree on a workflow step. Write a note on the disagreement and solution proposed and upload in App.', 'Proposes a logical compromise that addresses the primary concerns of both parties while strictly aligning with project constraints.'),
  ('teamwork', 4, 1, 6, 'Differentiate between minor misalignments and conflicts requiring escalation.', 'Evaluate a current conflict against an escalation matrix or established team protocols to determine the next step. Write differentiated escalation and upload in App.', 'Correctly identifies whether to mediate the issue locally or escalate it to the supervisor based on the conflict''s impact on budget, scope, or safety.'),
  ('teamwork', 4, 1, 7, 'Guide a deadlocked team towards a consensus decision.', 'Facilitate a brief, structured pros-and- cons analysis on a whiteboard for two competing technical options. Take a photo or screenshot of the pros and cons and upload in App.', 'Guides the involved team members to a unified decision, ensuring all parties agree to commit to the chosen path.'),
  ('teamwork', 4, 1, 8, 'Maintain strict neutrality and avoid taking sides in peer disputes.', 'Act as an impartial sounding board during a minor disagreement between two colleagues. Collect feedback from a third person involved in the meeting and upload in App.', 'Peer and supervisor feedback confirms the intern acted fairly, without expressing personal favouritism or bias toward either party.'),
  ('teamwork', 4, 1, 9, 'Document resolutions to prevent recurring misalignments.', 'Write a summary of the agreed-upon technical approach after a conflict is resolved and share it in the team channel. Upload the summary in App.', 'The documented resolution is clear, technically accurate, and formally acknowledged by all involved parties.'),
  ('teamwork', 4, 1, 10, 'Re-establish rapport and positive team dynamics after a disagreement.', 'Initiate a positive, forward-looking interaction or offer specific task assistance to the involved parties after a conflict is closed. collect evidence about the re-establishment using feedback or scripture and upload in App.', 'Demonstrates no lingering tension and successfully restores a normal, collaborative working rhythm with the peers involved.'),
  ('teamwork', 4, 2, 1, 'Assess the baseline knowledge of a peer before providing guidance.', 'Conduct a brief introductory conversation with a new team member to gauge their familiarity with a specific project tool or workflow. Rate their familiarity with a specific tool on the App.', 'Accurately identifies the peer''s knowledge gaps and tailors the subsequent explanation to match their specific experience level.'),
  ('teamwork', 4, 2, 2, 'Translate complex technical concepts into accessible language.', 'Explain a core project methodology or technical requirement to a junior peer using clear analogies and avoiding unnecessary jargon. Create a small presentation of any topic and explain it to a junior and upload the presentation in App.', 'The guided peer can accurately reiterate the core concept in their own words without relying on the original technical jargon.'),
  ('teamwork', 4, 2, 3, 'Utilize the "demonstrate- observe-correct" training method.', 'Perform a shadowing session where the intern executes a task while narrating the steps, then observes the newer peer attempting the same task. Write a report on the steps used by both parties and upload in App.', 'The new peer successfully replicates the task, with the intern providing immediate, constructive, and patient corrections when errors occur.'),
  ('teamwork', 4, 2, 4, 'Develop asynchronous support materials for peer learning.', 'Create a simple one-page "quick start guide" or a visual checklist for a routine team task to serve as a reference tool. Upload the quick start guide on App.', 'The created guide is clear, visually organized, technically accurate, and enables a new peer to complete the task independently.'),
  ('teamwork', 4, 2, 5, 'Foster a psychologically safe environment for questions', 'Dedicate specific time during a joint assignment for a Q&A session, explicitly encouraging the newer member to voice any uncertainties. Take photos or videos of the Q&A session and upload in App.', 'Feedback from the mentored peer highlights the intern''s patience, approachability, and non-judgmental demeanor when answering fundamental questions.'),
  ('teamwork', 4, 2, 6, 'Provide guidance while preserving peer autonomy.', 'Assign a manageable sub-task to a newer peer, provide initial context, and step back, offering support only when explicitly requested. Collect feedback about the availability from new peers and upload in App.', 'Strikes a successful balance between being available for support and allowing the peer to struggle constructively to find the solution without micromanagement.'),
  ('teamwork', 4, 2, 7, 'Deliver constructive and actionable feedback on peer work', 'Review a draft completed by a newer peer and provide specific, supportive, and actionable suggestions for improvement. Make a note of all the feedback suggested, made and upload in App.', 'Feedback is framed positively, focuses on the work rather than the individual, and provides concrete, step-by-step guidance for improvement.'),
  ('teamwork', 4, 2, 8, 'Guide newer members on unwritten workplace norms and culture.', 'Advise a new peer on appropriate team communication channels, meeting etiquette, or standard response times during their onboarding phase. Take a photo or video of the presentation and upload in App.', 'The new peer successfully integrates into team rhythms and utilizes communication tools appropriately based directly on the intern''s guidance.'),
  ('teamwork', 4, 2, 9, 'Connect peers to broader organizational resources and experts.', 'Introduce a newer peer to a specific colleague in another department who holds the expertise needed for their assigned task. The newer peer shall acknowledge the ability of introducing to other peers in App.', 'Successfully expands the newer peer''s internal network, equipping them to source information independently in the future.'),
  ('teamwork', 4, 2, 10, 'Evaluate the effectiveness of personal mentoring strategies.', 'Conduct a brief check-in a few days after guiding a peer to review their independent progress on the taught task. Make a small report on the peer if further training is required or ready for advanced tasks and upload the report in App.', 'Accurately assesses whether the peer needs further instruction or is ready for more advanced tasks and adjusts their support level accordingly.'),
  ('digital_tools', 1, 1, 1, 'Familiarize with the primary corporate email client.', 'Locate and successfully log into the company email system.', 'Intern logs into the email system and confirms inbox access.'),
  ('digital_tools', 1, 1, 2, 'Understand project management software.', 'Navigate to the active project dashboard within the PM tool.', 'Dashboard is located and active projects are identified.'),
  ('digital_tools', 1, 1, 3, 'Identify primary engineering/design software.', 'Open the designated CAD or BIM application on the workstation.', 'Application launches successfully without credential errors.'),
  ('digital_tools', 1, 1, 4, 'Locate cloud storage directories.', 'Find the shared departmental folder on the cloud drive.', 'Folder path is correctly identified and accessed.'),
  ('digital_tools', 1, 1, 5, 'Identify time-tracking and attendance tools.', 'Locate the timesheet application used for daily logging.', 'Application is opened and the current week is displayed.'),
  ('digital_tools', 1, 1, 6, 'Recognize internal messaging platforms.', 'Open the team chat application and find the departmental channel.', 'Chat application is active and the correct channel is joined.'),
