  ('digital_tools', 1, 1, 8, 'Identify HR and policy portals.', 'Locate the digital employee handbook on the company server.', 'Handbook is opened and the index is reviewed.'),
  ('digital_tools', 1, 1, 9, 'Familiarize with virtual meeting software.', 'Launch the video conferencing tool and access the settings menu.', 'Tool is running and audio/video settings are verified.'),
  ('digital_tools', 1, 1, 10, 'Recognize data visualization tools.', 'Open the company''s performance reporting dashboard.', 'Dashboard is viewed and basic metrics are noted.'),
  ('digital_tools', 1, 2, 1, 'Understand file naming conventions.', 'Review the documented file naming guide for engineering drawings.', 'Intern explains the standard convention accurately.'),
  ('digital_tools', 1, 2, 2, 'Observe daily data backup procedures.', 'Shadow a mentor during the end- of-day project data backup.', 'Intern summarizes the backup steps in a short note.'),
  ('digital_tools', 1, 2, 3, 'Comprehend data entry formats.', 'Review a completed engineering specification sheet.', 'Intern identifies all required data fields correctly.'),
  ('digital_tools', 1, 2, 4, 'Observe digital approval workflows.', 'Watch the submission of a design document for senior review.', 'Intern maps out the sequential approval steps.'),
  ('digital_tools', 1, 2, 5, 'Understand version control principles.', 'Review multiple versions of a CAD file in the repository.', 'Intern explains how previous versions are tracked and accessed.'),
  ('digital_tools', 1, 2, 6, 'Observe client communication logging.', 'Shadow the entry of meeting notes into the CRM system.', 'Intern describes the logging process and required metadata.'),
  ('digital_tools', 1, 2, 7, 'Understand confidentiality in data entry.', 'Review the corporate digital privacy guidelines.', 'Intern lists three key privacy rules relevant to their role.'),
  ('digital_tools', 1, 2, 8, 'Observe incident reporting workflows.', 'Review a completed digital safety incident report.', 'Intern identifies the mandatory fields for reporting an issue.'),
  ('digital_tools', 1, 2, 9, 'Comprehend digital task handoffs.', 'Observe a task reassignment in the project management tool.', 'Intern explains the handoff process and notification system.'),
  ('digital_tools', 1, 2, 10, 'Understand metadata requirements.', 'Review the tagging system used in the shared document repository.', 'Intern explains the purpose and structure of the applied tags.'),
  ('digital_tools', 2, 1, 1, 'Use project boards to track status.', 'Move an assigned task from ''To Do'' to ''In Progress'' in the tracking app.', 'Task status is accurately updated within the software.'),
  ('digital_tools', 2, 1, 2, 'Share digital files securely.', 'Generate and share a view-only link to a project document with a peer.', 'Link is accessible and permissions are correctly set to view-only.'),
  ('digital_tools', 2, 1, 3, 'Log daily activities digitally.', 'Enter the day''s completed tasks into the digital timesheet tool.', 'Timesheet reflects accurate task descriptions and hours.'),
  ('digital_tools', 2, 1, 4, 'Document meeting takeaways.', 'Type a brief summary of a stand-up meeting in the team chat.', 'Summary is clear, concise, and posted promptly.'),
  ('digital_tools', 2, 1, 5, 'Utilize document comment features.', 'Add a clarifying question as a comment on a draft specification doc.', 'Comment is clear and tagged correctly for the mentor.'),
  ('digital_tools', 2, 1, 6, 'Update personal digital calendar.', 'Add a scheduled software training session to the digital calendar.', 'Calendar event has correct time, location link, and details.'),
  ('digital_tools', 2, 1, 7, 'Use basic digital drafting tools.', 'Create a simple 2D sketch using the organizational CAD software.', 'Sketch is saved to the cloud and meets basic parameters.'),
  ('digital_tools', 2, 1, 8, 'Document bug/issue reports.', 'Draft a simple IT ticket for a minor software glitch encountered.', 'Ticket contains necessary descriptive details and screenshots.'),
  ('digital_tools', 2, 1, 9, 'Share screen during virtual meetings.', 'Share a specific application window during a progress call.', 'Screen is visible to all participants without showing background apps.'),
  ('digital_tools', 2, 1, 10, 'Utilize cloud collaboration features.', 'Co-edit a tracking spreadsheet simultaneously with a mentor.', 'Edits are saved and conflict- free in real-time.'),
  ('digital_tools', 2, 2, 1, 'Record material specifications.', 'Input dimensional data into the engineering database from a source doc.', 'Data matches the source document exactly without typos.'),
  ('digital_tools', 2, 2, 2, 'Enter testing results digitally.', 'Record the outcomes of a quality control test in the digital system.', 'Results are logged without errors and timestamped correctly.'),
  ('digital_tools', 2, 2, 3, 'Update inventory levels.', 'Log the use of prototype components in the digital inventory tracker.', 'Inventory counts accurately reflect the deducted components.'),
  ('digital_tools', 2, 2, 4, 'Record field observations.', 'Input site visit notes into the EngineerTrack mobile application.', 'Notes are comprehensive, legible, and successfully synced to the cloud.'),
  ('digital_tools', 2, 2, 5, 'Input client feedback.', 'Transcribe written client comments into the digital CRM.', 'Transcription is accurate, complete, and linked to the right client.'),
  ('digital_tools', 2, 2, 6, 'Update project milestones.', 'Mark a sub-task as 100% complete in the project tracker.', 'Milestone reflects the correct completion date and triggers the next phase.'),
  ('digital_tools', 2, 2, 7, 'Record safety compliance data.', 'Fill out the digital daily safety checklist before commencing work.', 'Checklist is fully completed and submitted to the supervisor.'),
  ('digital_tools', 2, 2, 8, 'Log equipment maintenance.', 'Enter the details of a 3D printer calibration into the digital log.', 'Log entry contains date, time, and recorded calibration values.'),
  ('digital_tools', 2, 2, 9, 'Input budgetary expenses.', 'Record a minor project material purchase into the expense tracker.', 'Amount, category, and receipt image are correctly entered.'),
  ('digital_tools', 2, 2, 10, 'Update drawing revisions.', 'Add a revision note and date to the digital drawing metadata.', 'Metadata accurately reflects the change made to the drawing.'),
  ('digital_tools', 3, 1, 1, 'Apply advanced spreadsheet functions.', 'Create a pivot table to summarize monthly material costs from raw data.', 'Pivot table accurately reflects data grouped by material type and cost.'),
  ('digital_tools', 3, 1, 2, 'Utilize complex CAD features.', 'Apply parametric constraints to a 3D component model.', 'Model updates dynamically without errors when base dimensions are changed.'),
  ('digital_tools', 3, 1, 3, 'Manage advanced project tracking.', 'Set up a Gantt chart view for a small sub-project within the PM tool.', 'Gantt chart displays accurate task dependencies and critical paths.'),
  ('digital_tools', 3, 1, 4, 'Use digital simulation software.', 'Run a basic stress analysis simulation on a completed CAD part.', 'Simulation executes successfully and generates a preliminary report.'),
  ('digital_tools', 3, 1, 5, 'Implement automated workflows.', 'Set up an automated email notification for when a form is submitted.', 'Notification triggers correctly upon a test form submission.'),
  ('digital_tools', 3, 1, 6, 'Use data extraction tools.', 'Export a customized report from the CRM in CSV format.', 'CSV file contains the requested data fields formatted correctly.'),
  ('digital_tools', 3, 1, 7, 'Leverage cloud access controls.', 'Configure a shared folder with specific read/write permissions for different users.', 'Permissions restrict editing access appropriately based on user roles.'),
  ('digital_tools', 3, 1, 8, 'Use digital mock-up tools.', 'Create a digital wireframe or mockup for a proposed interface.', 'Wireframe includes all required interactive elements for demonstration.'),
  ('digital_tools', 3, 1, 9, 'Perform advanced document formatting.', 'Apply automated table of contents and heading styles to a 10-page report.', 'Table of contents updates automatically with pagination changes.'),
  ('digital_tools', 3, 1, 10, 'Utilize advanced search operators.', 'Perform a boolean search within the corporate database to find specific historical records.', 'Search yields precise, relevant documents excluding unrelated files.'),
  ('digital_tools', 3, 2, 1, 'Connect CAD to CAM tools.', 'Export a 3D model and import it seamlessly into the manufacturing software.', 'Model imports without missing geometries or scaling errors.'),
  ('digital_tools', 3, 2, 2, 'Link spreadsheets to presentations.', 'Embed a live-updating data chart from a spreadsheet into a presentation slide.', 'Chart reflects changes made in the source spreadsheet automatically.'),
  ('digital_tools', 3, 2, 3, 'Sync mobile and desktop apps.', 'Capture field data via the mobile app and verify its presence on the desktop dashboard.', 'Data syncs accurately and instantly between platforms.'),
  ('digital_tools', 3, 2, 4, 'Integrate email and task management.', 'Convert a client email request directly into a tracked task using software integration.', 'Task includes the original email text and attachments as context.'),
  ('digital_tools', 3, 2, 5, 'Consolidate financial data.', 'Import expense receipts from a scanning app into the central accounting software.', 'Receipts are categorized and attached to the correct expense entries.'),
  ('digital_tools', 3, 2, 6, 'Use API endpoints for basic data pull.', 'Extract weather data using a simple API query to append to an environmental report.', 'Data is successfully retrieved and integrated into the document.'),
  ('digital_tools', 3, 2, 7, 'Transfer data between legacy and new systems.', 'Migrate a set of older component files into the new cloud repository, updating metadata.', 'Files are accessible in the new system with all tags intact.'),
  ('digital_tools', 3, 2, 8, 'Integrate scheduling with conferencing.', 'Set up a project calendar that automatically generates virtual meeting links.', 'Calendar invites contain functional links without manual generation.'),
  ('digital_tools', 3, 2, 9, 'Connect inventory to procurement tools.', 'Trigger an automated digital purchase order request when inventory falls below a threshold.', 'System generates the order request automatically upon stock depletion.'),
  ('digital_tools', 3, 2, 10, 'Compile multi- source reports.', 'Combine outputs from the PM tool, CAD software, and CRM into one final PDF portfolio.', 'PDF is cohesive, appropriately formatted, and comprehensively covers all sources.'),
  ('digital_tools', 4, 1, 1, 'Diagnose software crashes.', 'Investigate and document the error logs of a recurrent software crash on a workstation.', 'Log analysis identifies the root cause or provides actionable details for IT.'),
  ('digital_tools', 4, 1, 2, 'Optimize tool performance.', 'Adjust hardware acceleration and cache settings in the CAD software to improve render times.', 'Render times decrease without compromising graphical output quality.'),
  ('digital_tools', 4, 1, 3, 'Resolve file corruption issues.', 'Restore a corrupted project file from a verified backup source without data loss.', 'File is successfully recovered and functional for the team.'),
  ('digital_tools', 4, 1, 4, 'Customize software interfaces.', 'Create a custom toolbar or macro in the primary design software for frequently used commands.', 'Custom toolbar functions correctly and increases workflow speed.'),
  ('digital_tools', 4, 1, 5, 'Troubleshoot sync errors.', 'Resolve a cloud synchronization conflict where two users edited a file simultaneously.', 'Conflict is resolved by merging changes without losing either user''s work.'),
  ('digital_tools', 4, 1, 6, 'Audit digital security.', 'Conduct a self-audit of personal workstation security settings and update necessary protocols.', 'Workstation passes the organizational IT security compliance check.'),
  ('digital_tools', 4, 1, 7, 'Optimize database queries.', 'Refine a search query in the CRM to reduce loading times for large datasets.', 'Query returns identical accurate results in significantly less time.'),
  ('digital_tools', 4, 1, 8, 'Manage software updates.', 'Safely execute a required software patch update on the workstation, verifying functionality post-update.', 'Software operates normally with the new patch installed.'),
  ('digital_tools', 4, 1, 9, 'Resolve connectivity issues.', 'Troubleshoot a VPN disconnection issue to re-establish secure access to the company server.', 'Secure connection is restored and server files are accessible.'),
  ('digital_tools', 4, 1, 10, 'Evaluate new digital tools.', 'Test a trial version of a new productivity app and write a brief pros/cons review for the team.', 'Review provides a clear, technically sound recommendation on adoption.'),
  ('digital_tools', 4, 2, 1, 'Create digital tool tutorials.', 'Record a 3-minute screen-capture tutorial demonstrating how to use the new expense software.', 'Tutorial is clear, covers all steps, and is uploaded to the team wiki.'),
  ('digital_tools', 4, 2, 2, 'Mentor peers on software usage.', 'Assist a junior intern with setting up their project management dashboard.', 'Peer''s dashboard is fully operational and they understand how to use it.'),
  ('digital_tools', 4, 2, 3, 'Standardize digital templates.', 'Design and distribute a standardized digital template for weekly team reporting.', 'Template is adopted by the team and reduces formatting inconsistencies.'),
  ('digital_tools', 4, 2, 4, 'Enforce data hygiene.', 'Conduct a review of the shared drive and archive outdated project folders.', 'Shared drive is reorganized according to retention policies.'),
  ('digital_tools', 4, 2, 5, 'Lead a software onboarding session.', 'Host a brief Q&A session for the team regarding the latest updates to the CAD software.', 'Questions are answered accurately, resolving team confusion.'),
  ('digital_tools', 4, 2, 6, 'Develop digital SOPs.', 'Draft a Standard Operating Procedure document for handling digital client data securely.', 'SOP is comprehensive and approved by the IT or management team.'),
  ('digital_tools', 4, 2, 7, 'Facilitate digital collaboration.', 'Set up and moderate a digital brainstorming board (e.g., Miro) for a design charrette.', 'Board is well-structured and team members interact seamlessly.'),
  ('digital_tools', 4, 2, 8, 'Advocate for digital accessibility.', 'Ensure all team presentations are updated with alt-text for images and readable contrast.', 'Presentations meet basic accessibility standards.'),
  ('digital_tools', 4, 2, 9, 'Review peer digital outputs.', 'Perform a quality check on a peer''s data entry batch before final submission.', 'Errors are caught and corrected prior to database integration.'),
  ('digital_tools', 4, 2, 10, 'Propose workflow automations.', 'Present a proposal to automate the generation of weekly status reports using existing tools.', 'Proposal outlines the logic, tools needed, and estimated time savings.'),
  ('problem_solving', 1, 1, 1, 'To identify the main technical problems encountered in the given tasks.', 'Spotting visible technical errors in operational tasks performed in virtually rendered 3D environments or videos.', 'Successfully indentifies visible technical errors in a virtual environment (3D/video) by clicking on the correct points within the time limit.'),
  ('problem_solving', 1, 1, 2, 'To identify fundamental deviations from the expected operating conditions of a system, product, or process.', 'Identify deviations by matching the virtual system''s operational data displayed on the screen with standard reference values using a "drag-and-drop" method.', 'Groups the operational data of the virtual system displayed on the screen correctly using the "drag- and-drop" method without incorrect matching.'),
  ('problem_solving', 1, 1, 3, 'To express the problem by observing the symptoms of technical issues.', 'By examining the encountered physical symptoms or error messages, select the correct technical terms from the in-app menu to identify the problem.', 'Accurately describes the problem with 100% precision by selecting the most appropriate technical terms from an interactive menu based on the symptoms or error messages encountered.'),
  ('problem_solving', 1, 1, 4, 'To collect basic, surface-level data and observation results related to the problem.', 'Collecting measurement data, images, and user feedback from virtual devices in the application interface and transferring them to a digital dashboard.', 'Collects all required measurement data and visuals from virtual devices without skipping anything and transfers them completely to the in-game digital scoreboard.'),
  ('problem_solving', 1, 1, 5, 'To identify potential technical issues by reviewing the requirements of assigned tasks.', 'In the app, identify potential problem areas and risk points in job descriptions and workflows by marking them with an interactive highlighter.', 'Highlights all potential risk areas in the workflows within the scenario in a comprehensive and interconnected manner using an interactive pen.'),
  ('problem_solving', 1, 1, 6, 'To identify the scope of the technical issues encountered and the components affected.', 'Mapping the area affected by the technical issue by selecting each piece of equipment, module, and component individually on the interactive system diagram in the app.', 'Accurately and clearly maps all components affected by the technical problem on an interactive diagram, eliminating the need for incorrect part selection.'),
  ('problem_solving', 1, 1, 7, 'To identify simple, superficial technical errors, deficiencies, or irregularities.', 'Performing visual inspections on virtual equipment to identify and label superficial errors and deficiencies.', 'During a virtual visual inspection, identifies all surface defects and physical deficiencies without missing and labels them with the correct names.'),
  ('problem_solving', 1, 1, 8, 'To make a preliminary assessment of the source of technical problems and listing possible causes.', 'Based on observation results for various technical problem scenarios presented in the application, drag and drop logical causes from a pool of possible solutions to create a preliminary evaluation list.', 'Accurately selects possible causes from the pool that logically match the observational data, creating a complete preliminary assessment list.'),
  ('problem_solving', 1, 1, 9, 'To record any technical issues identified using appropriate tools such as checklists, trouble tickets, and reports.', 'Reporting issues to the system by filling out the digital trouble ticket form and checklists within the application.', 'Completes all required fields on the digital trouble ticket and checklists with accurate technical information and approves the form.'),
  ('problem_solving', 1, 1, 10, 'To perform the necessary basic checks to confirm the presence of technical issues.', 'Confirm or deny the presence of a problem by simulating the basic checks specified in the procedure using virtual measurement tools.', 'To confirm the problem, simulates the essential checks required, using virtual measurement tools and strictly following the standard procedure.'),
  ('problem_solving', 1, 2, 1, 'To describe the basic steps engineers follow when identifying a technical problem.', 'A puzzle to arrange event cards, which illustrate an engineer''s problem definition process, such as data collection, testing, etc., in chronological order.', 'Arranges the event cards, which illustrate the problem definition steps, in a logical and chronologically perfect order on the first attempt.'),
  ('problem_solving', 1, 2, 2, 'To describe the observation methods used in the process of identifying a problem.', 'A mini game that matches various observation scenarios, such as field inspections and performance monitoring, with the correct observation method names.', 'Completes various observation scenarios with the corresponding observation method names (for example field inspection, etc.) without mismatching.'),
  ('problem_solving', 1, 2, 3, 'To list the types of data engineers collect for the purpose of problem identification.', 'Separate the displayed sensor data, log records, and feedback into the appropriate data type folders, such as qualitative/quantitative, etc. by dragging and dropping.', 'Correctly classifies different data types as qualitative/quantitative, etc. displayed on the screen by accurately shifting them to their respective folders within a time constraint.'),
  ('problem_solving', 1, 2, 4, 'To describe the measurement, testing, and inspection activities used in identifying technical problems.', 'The measurement and testing simulations are conducted in a virtual environment, and in- game flashcards are used to answer questions about the purpose of each.', 'After virtual test simulations, provides technically correct answers to the objective or scope questions presented on the flashcards.'),
  ('problem_solving', 1, 2, 5, 'To describe the fundamental questions and inquiry techniques engineers use when defining a problem.', 'In a problem scenario, select the most appropriate inquiry technique or question from an interactive dialogue tree to find the root cause.', 'In the interactive dialogue tree, the most accurate inquiry route to finding the root cause, rather than focusing on superficial symptoms, is found in a logical flow.'),
  ('problem_solving', 1, 2, 6, 'To understand the process by which engineers distinguish between the symptoms and root causes of a technical problem.', 'Separate the mixed fault conditions by swiping them into "Symptom" or "Root Cause" boxes.', 'Separates whether the information on the fault cards it encounters is a "Symptom" or a "Root Cause" by swiping it into boxes with 100% accuracy.'),
  ('problem_solving', 1, 2, 7, 'To describe the documentation and record-keeping methods engineers use during the problem identification process.', 'Documenting the process by correctly matching the appropriate documentation format, such as failure report, maintenance log, etc. for a case study in a virtual environment.', 'Correctly selects and matches the most appropriate documentation format, such as failure report, maintenance log, etc. that meets the technical requirements of the given case scenario.'),
  ('problem_solving', 1, 2, 8, 'To identify common elements in problem- identification approaches applied to different technical problems.', 'Identify common diagnostic steps in different technical failure cases and combine them on an interactive Venn diagram.', 'By analysing the steps of different failure cases, it accurately places the intersecting common diagnostic steps at the center of the interactive Venn diagram.'),
  ('problem_solving', 1, 2, 9, 'To observe the problem- identification process conducted by an engineer and list its stages.', 'While watching a short video of a virtual process, pause the screen at critical stages and record the steps of the process in a timeline.', 'In the virtual process it monitors, pauses the video precisely at the critical breaking points where the engineer takes action, recording the process step by step in a time tunnel.'),
  ('problem_solving', 1, 2, 10, 'To describe the observed problem- identification process verbally or in writing using technical terminology.', 'Drag and drop the appropriate terms from the in-app technical vocabulary pool to fill in the blanks in the summary text of the observed process.', 'Accurately fills in the gaps in the summary text of the observed process using correct words selected from a pool of technical terminology.'),
  ('problem_solving', 2, 1, 1, 'To understand the fault diagnosis plan and methodological steps to be followed for engineering problems.', 'Set a logical workflow diagram by dragging and dropping the complex diagnostic steps as troubleshooting roadmap provided under mentor guidance.', 'Places the mixed diagnostic steps provided by the mentor into the diagram in their complete and correct order, in accordance with the system''s logical workflow rules.'),
  ('problem_solving', 2, 1, 2, 'To collecting and present the required technical data for specific fault types or anomalies within the scope of engineering problems.', 'Systematically extract critical parameters, such as temperature, pressure from virtual device screens and enter them into a digital reporting table.', 'Reads all critical parameters, such as temperature, pressure, etc. displayed on the virtual device screens without missing and records the correct values in the digital reporting table.'),
  ('problem_solving', 2, 1, 3, 'To use basic engineering fault diagnosis and testing tools safely and accurately as required.', 'Reading and recording error codes using diagnostic simulations such as virtual multimeters and oscilloscopes, while adhering to occupational safety and health (OSH) rules.', 'By using virtual testing devices in accordance with occupational safety and health (OSH) rules, in the correct sequence and with the correct calibration settings, it accurately detects error codes.'),
  ('problem_solving', 2, 1, 4, 'To compare engineering problem symptoms with technical documentation and reference values.', 'Review the P&IDs and electrical schematics (CAD) in the application to identify and mark any deviations between physical failure indicators and reference values.', 'By reviewing the P&IDs and electrical schematics (CAD) in the system, accurately identifies and clearly marks any deviations between physical fault indicators and reference values.'),
  ('problem_solving', 2, 1, 5, 'To contribute structured ideas to ongoing Root Cause Analysis (RCA) processes under mentor guidance.', 'Fill in the missing causal branches in the interactive fishbone (Ishikawa) pattern, opened with the guidance of the mentor in the application, using the technical tips provided.', 'Fills in the blank cause-and- effect branches in the interactive fishbone diagram with correct arguments by logically analysing the technical clues in the system.'),
  ('problem_solving', 2, 1, 6, 'To perform validation experiments or tests conducted by the mentor to identify the source of the problem.', 'Perform functional tests by preserving or modifying the virtual parameters defined by the mentor, and record any changes made to the interface in real time.', 'Manipulates the virtual parameters in full accordance with the mentor''s testing instructions and records the system''s real-time reactions to the interface with zero latency.'),
  ('problem_solving', 2, 1, 7, 'To record the steps taken and interim findings in the diagnostic process using technical language.', 'Adding each intervention in the fault diagnosis process or simulation to the technical logbook chronologically with a timestamp.', 'Records all technical interventions in the fault diagnosis simulation in the digital logbook, without omitting any, along with the correct timestamps and engineering terminology.'),
  ('problem_solving', 2, 1, 8, 'To observe the distinction between systemic/structural failures and normal operational wear and tear and contributing to the diagnostic process.', 'Compare the visual examples and indicate whether the condition constitutes “Acceptable Wear and Tear” or “Systematic Error”.', 'By analysing images of damaged/worn parts, it assigns "Acceptable Wear" and "Systematic Error" labels to the correct cases with 100% accuracy.'),
  ('problem_solving', 2, 1, 9, 'To visualize diagnostic data for technical reporting and presentations.', 'Create interactive trend curves and graphs with adjusted axes and tolerances using the raw test data provided by the application. Upload these to the system.', 'Using raw test data, draws readable, interactive graphs with accurately calibrated axis designations, units, and engineering tolerance limits. uploads these to the system.'),
  ('problem_solving', 2, 1, 10, 'To supporting final reporting and decision- making processes towards definitive diagnosis.', 'Analyse all the findings and select the most logical diagnosis from the options provided for the “Conclusions and Recommendations” section of the prepared virtual fault report.', 'By synthesizing all the data collected in the virtual environment and the mentor tips, selects the most accurate diagnosis from the multiple- choice options presented for the report''s “Conclusions and Recommendations” section.'),
  ('problem_solving', 2, 2, 1, 'To understand accepted troubleshooting procedures and standard operating guidelines for simple technical problems.', 'For a selected fault resolution, read the steps of the relevant Standard Operating Procedure (SOP) and follow the digital workflow by checking the boxes.', 'Reads all the steps of the Standard Operating Procedure (SOP) for the troubleshooting solution without skipping any, and checks the boxes on the digital workflow in the correct order.'),
  ('problem_solving', 2, 2, 2, 'To prepare the necessary technical materials, components, and equipment for solving simple technical problems.', 'Before starting the process, select the appropriate tools and spare parts from the application''s virtual inventory and add them to your virtual toolkit.', 'From the app’s virtual inventory, adds all the hand tools, consumables, and technical specifications required for the task along with the correct spare parts to the virtual toolbox without omission.'),
  ('problem_solving', 2, 2, 3, 'To perform standard repair or part replacement procedures under supervision.', 'Complete the animation of removing, replacing, and installing a new mechanical/electrical component in the simulation, following standard procedures.', 'Completes the component disassembly and assembly animation/simulation steps in full compliance with occupational safety and health (OSH) regulations and the technical assembly sequence, without encountering any system errors.'),
  ('problem_solving', 2, 2, 4, 'To apply standard calibration and adjustment procedures on systems or products.', 'Aligning and calibrating device sensors or mechanical parts to their nominal reference values using virtual sliders on a simulation.', 'By using virtual sliders with precision, accurately calibrates the device’s sensors or mechanical components within the tolerance range permitted by the system.'),
  ('problem_solving', 2, 2, 5, 'To report unexpected intermediate technical challenges encountered during solution implementation.', 'Report any software/mechanical anomalies encountered during the simulation process instantly using the application''s "Live Support/Report" tool.', 'Instantly detects scenario-based unexpected software/hardware anomalies during application and enters them into the "Live Report" screen using accurate engineering language.'),
  ('problem_solving', 2, 2, 6, 'To apply standard test procedures to verify the effectiveness of the implemented solution.', 'After repair, trigger leak, load, and continuity test scenarios in the virtual system and record the pass/fail data.', 'After the repair simulation, triggers the appropriate tests, such as leakage, load, etc. in a timely manner to validate the system and reports the results on the screen according to the validation criteria.'),
  ('problem_solving', 2, 2, 7, 'To compare and schematizing post- solution performance data with design reference values.', 'Comparing the performance outputs obtained after implementing the solution with the original design data on a digital schematic.', 'Analyses the system''s post- solution performance metrics by overlaying them onto the digital comparison diagram with the original catalogue design data without any data loss'),
  ('problem_solving', 2, 2, 8, 'To document the steps and changes of the implemented technical solution in a professional format.', 'Completely enter the serial numbers of the new parts used and the final test results into the company-formatted digital maintenance form (database).', 'Records the serial numbers of newly integrated components and the final verification results completely and permanently in the digital maintenance database without formatting errors.'),
  ('problem_solving', 2, 2, 9, 'To provide standard preventive maintenance recommendations to ensure the longevity of the solution.', 'Drag and drop preventative maintenance recommendations, such as cleaning or calibration routines, into the system to prevent recurrence of the problem.', 'To prevent the problem from recurring, integrates the most appropriate preventive maintenance recommendations such as lubrication, cleaning, etc. into the system, drawing them from a pool of recommendations to extend the system''s lifespan.'),
  ('problem_solving', 2, 2, 10, 'To support the completion of the solution process and system commissioning activities.', 'Approving the interim tasks assigned during system commissioning and digitally signing the handover form to the operations team. Uploading this form to the system.', 'By fully completing all safety and control sub-tasks in the system commissioning scenario, the user successfully approves the digital handover form and uploads it to the system.'),
  ('problem_solving', 3, 1, 1, 'To independently define an encountered engineering problem, including its scope, boundary conditions, technical requirements, and expected outcomes.', 'Taking character limits into account, describe the boundary conditions, constraints, and expected results of a virtual problem scenario in an interactive “Problem Definition Document.”', 'Formulates the boundary conditions, technical constraints, and outputs of the simulation scenario as a complete summary, in accordance with technical terminology and within the character limits of the “Problem Definition Document”'),
  ('problem_solving', 3, 1, 2, 'To identify the necessary technical data for the problem, collect it from appropriate sources, and prepare it for analysis.', 'Combining relevant data from different digital databases, including historical maintenance logs and sensor data, into a single analysis workspace.', 'Retrieves the necessary sensor and maintenance log data for diagnosis from multiple digital databases with zero loss and combines them into a single, cleaned dataset pool ready for analysis.'),
  ('problem_solving', 3, 1, 3, 'To evaluate the accuracy, reliability, and suitability of the collected data from an engineering perspective.', 'Filter calibration errors, outliers, and missing data on the dataset by clicking through an interactive chart.', 'Finds and clicks on all manipulated calibration errors and statistical outliers in the data graph, bringing the dataset to 100% accuracy.'),
  ('problem_solving', 3, 1, 4, 'To use methods such as observation, measurement, comparison, cause-and- effect analysis, or root cause analysis to identify the root causes of the problem.', 'Fill in a blank "Fishbone" diagram or "5 Whys" table with interactive blocks to identify root causes through independent analysis.', 'To get past the superficial symptoms of the problem and find the root cause, constructs Fishbone blocks flawlessly with logical arguments that perfectly fit the causal link.'),
  ('problem_solving', 3, 1, 5, 'To quantitatively analyse the effects of the problem using field data, measurement results, production records, maintenance history, or performance indicators.', 'Measure the impact of a given problem on system performance using a digital mini-calculator and visualize it with trend lines.', 'Measures the negative numerical impact of the problem, such as production/energy loss, etc. on the system using a digital mini- calculator and accurate mathematical metrics and presents the results in a clear trend graph.'),
  ('problem_solving', 3, 1, 6, 'To develop alternative technical approaches to solve the problem and evaluate these alternatives in terms of feasibility.', 'Create at least three different solution concepts for an identified root cause as digital design cards, such as plans A, B, and C.', 'Enter at least three independent, innovative solution scenarios cards into the system that directly address the root cause, are technically feasible, and do not conflict with engineering principles.'),
  ('problem_solving', 3, 1, 7, 'To compare solution alternatives according to criteria such as performance, cost, time, safety, quality, and sustainability.', 'Add alternative solution plans to the decision matrix module on the application and score them according to time, cost, and safety criteria.', 'Places the alternative solution plans into the decision matrix and evaluates each alternative with analytical and objective scores based on the system''s cost, performance, and security constraints.'),
  ('problem_solving', 3, 1, 8, 'To select the most appropriate solution based on a data-driven evaluation and support the selection with technical justifications.', 'Select the highest-scoring solution in the decision matrix and enter the digital justification document into the system, including quantitative analyses such as return on investment (ROI) and payback period.', 'Successfully defends the optimal solution derived from the matrix analysis with a strong digital business case based on numerical data and evidence, such as ROI and payback period. He uploads this document to the system.'),
  ('problem_solving', 3, 1, 9, 'To present the results of the analysis and evaluation in an organized manner using graphs, tables, calculations, presentations, or technical reports.', 'Present a structured technical solution report dashboard, consisting of data tables, root cause diagrams, and a decision matrix, to the virtual project manager or mentor via the digital platform.', 'Presents all diagrams, tables, and numerical arguments in a visually coherent "Technical Solution Dashboard" format, suitable for professional engineering, for virtual approval.'),
  ('problem_solving', 3, 1, 10, 'To evaluate the technical risks, uncertainties, and limitations that may arise during the implementation of the proposed solution.', 'Anticipate potential installation or safety challenges during the solution''s field implementation by adding them to an interactive "Risk Assessment Table" on the digital platform.', 'Maps all technical and operational risk thresholds that may arise during the integration of the proposed solution in the field onto an interactive heat map with accurate severity values.'),
  ('problem_solving', 3, 2, 1, 'To appropriately identify the technical problems determined within the scope of the project for solution development.', 'Virtually navigate through virtually generated project plans and PID diagrams to identify design conflicts and bottlenecks using markers.', 'By reviewing the virtual project plan (PID or CAD), accurately identifies and marks bottlenecks and design conflicts on the map that hinder the overall project flow.'),
  ('problem_solving', 3, 2, 2, 'To evaluate the impact of the identified problem on project objectives, workflow, product quality, process efficiency, or system performance.', 'Calculate the quantitative impact of the identified bottlenecks on the project schedule and budget, such as days of delay, and enter the results into the virtual briefing module.', 'Accurately calculates the numerical impact of identified bottlenecks on the project''s time and budget targets, causing delays or increasing costs, and transmits this data flawlessly to the briefing module.'),
  ('problem_solving', 3, 2, 3, 'To develop multiple technical solution alternatives for the problem determined within the scope of the project.', 'Develop at least two innovative solution scenarios from different perspectives, such as design revision or process change, in the implementation scenario module.', 'To overcome project constraints, writes at least two independent, technically sound alternative scenarios that either manipulate the existing hardware or alter the process sequence. Then, uploads these into the relevant module in the system.'),
  ('problem_solving', 3, 2, 4, 'To compare the proposed solution alternatives in terms of feasibility, cost, time, occupational safety, and technical competence.', 'Test the developed solutions using a cost-benefit analysis tool in the app to find the one that best suits the project constraints.', 'By inputting their solutions into a virtual cost-benefit analysis tool, analytically identifies the scenario that maximizes the project''s work safety, time, and budget balance.'),
  ('problem_solving', 3, 2, 5, 'To develop solution proposals that are compatible with current project conditions, organizational resources, existing equipment, and current procedures.', 'Solving a resource optimization puzzle that can be implemented within the existing workshop boundaries without requiring the purchase of external parts.', 'Without requiring any external procurement approval, builds a fully compatible and realistic solution by optimizing the limited resource pool of the virtual workshop provided by the application.'),
  ('problem_solving', 3, 2, 6, 'To use observations, measurements, technical documents, standards, or field data when developing feasible solution proposals.', 'Linking international engineering standards (ISO, DIN, IEEE standards) from the digital library as references to the proposed solution.', 'Successfully links the proposed design to the most accurate manufacturer''s catalog page or international engineering standard (ISO, DIN, IEEE standards) found in the digital archive.'),
  ('problem_solving', 3, 2, 7, 'To explain the expected technical benefits and contribution of the selected solution proposal to the project process.', 'Predicting the benefits of the designed solution (e.g., a 15% increase in engine efficiency) using metrics and reflecting them in an interactive benefit table within the digital application.', 'Calculates the performance improvements or time savings that the solution will deliver in the field using sound engineering metrics (e.g., percentage increase) and presents them persuasively in a “benefits table” within the digital application.'),
  ('problem_solving', 3, 2, 8, 'To identify the limitations, risks, and potential side effects that may arise during the implementation of the proposed solution.', 'Record any side effects the new solution might cause in existing modules (e.g., overheating, pressure fluctuations) as “warning notes” in the interactive system.', 'After the integration of the designed method, it anticipates potential technical side effects, such as pressure drop in other system modules and leaves appropriate warning notes within the system.'),
  ('problem_solving', 3, 2, 9, 'To present the solution proposal, along with its technical justification, to the consultant, responsible engineer, or project team in a clear and understandable manner.', 'Present the elevator pitch (pitch & record) to the project team or virtual characters, including solution arguments and 3D CAD models, via the system.', 'Completes her 3D model- supported technical elevator presentation before the timer runs out, using sound engineering arguments and maintaining her excellent communication skills'),
  ('problem_solving', 3, 2, 10, 'To review the solution proposal based on feedback received and adapt it to the scope of the project.', 'During the virtual review meeting, note the constructive technical feedback from other engineers in the digital agenda and revise the model.', 'Carefully filters revision requests and criticisms from the virtual evaluation jury, revising its model to perfectly match this specific technical feedback.'),
  ('problem_solving', 4, 1, 1, 'To apply advanced analytical methods to identify the root causes of multidimensional and complex engineering problems.', 'Analysing and visualizing complex root-cause networks using data mining methods in a “Fault Tree Analysis (FTA)” simulation in the app.', 'Using the "Fault Tree Analysis (FTA)" algorithm in complex, multi- dimensional cases, maps interconnected main and sub-root cause networks without logical discontinuity.'),
  ('problem_solving', 4, 1, 2, 'To design and formulate multiple alternative solutions for the identified complex problems.', 'Drawing innovative, feasible, and alternative concept designs for a multi-dimensional problem in an interactive modelling environment.', 'In large-scale crisis situations or complex design problems, builds two highly feasible, innovative, and completely different main scenario models (for example, Plan A and B) at the interface.'),
  ('problem_solving', 4, 1, 3, 'To select the most appropriate solution by comparing the alternatives based on engineering constraints such as cost, time, performance, safety, etc.', 'Filtering the most optimal solution by weighting constraints such as time, cost, and security in the application''s algorithmic decision matrix using a slider.', 'By adjusting the weighted decision matrix in the system to the optimal level based on the project’s strategic constraints, selects the mathematically best solution to the multi-variable equation.'),
  ('problem_solving', 4, 1, 4, 'To anticipate technical, operational, and environmental risks that may arise during the implementation of developed solutions.', 'By fast-forwarding the simulation of the selected solution in the app, potential technical/environmental risks that may arise during installation are incorporated into a risk heatmap.', 'By running the solution simulation, instantly identifies hidden and long- term environmental and technical risks, and records them in the correct probability and impact zones on the comprehensive heatmap.'),
  ('problem_solving', 4, 1, 5, 'To develop proactive preventive measures and emergency action plans to minimize identified risks.', 'Writing emergency action plans and proactive response strategies that can be activated through the system during a crisis for high- priority risks.', 'Logically loads “Emergency Protocols” into the system that safely shut down the system or switch it to an alternative path when risk scenarios in the red zone occur.'),
  ('problem_solving', 4, 1, 6, 'To test the validity of solutions using simulation, computer- aided modeling, or prototyping tools.', 'The selected solution is built in a virtual simulation environment and validated by subjecting it to various stress, leakage, and load test scenarios.', 'Places the digital prototype in a virtual stress environment and proves the validity of its solution by accurately analysing the design’s failure points in the out-of-limit leakage/load simulations it performs.'),
  ('problem_solving', 4, 1, 7, 'To establish a holistic and integrated solution architecture by breaking down problems requiring multidisciplinary approaches into subsystems.', 'Dividing multidisciplinary problems into subsystems, such as mechanical, software, etc. and establishing a holistic architecture by mapping inter-module connection diagrams on the interface.', 'Combines subsystem modules from different engineering disciplines such as software, automation, mechanics in a way that fully complies with logical interface rules, creating a complete and functional integrated architecture.'),
  ('problem_solving', 4, 1, 8, 'To analyse the impacts of integrating developed solutions into existing systems and resolve any incompatibilities.', 'Running a simulation to integrate the newly developed module into the existing system infrastructure and correcting any potential conflicts.', 'During the integration of the new solution, instantly detects and resolves any data or physical connection conflicts with the old system, leaving zero errors.'),
  ('problem_solving', 4, 1, 9, 'To identify bottlenecks and propose sustainable improvement plans to enhance the system’s long-term performance.', 'Identify capacity limits by analysing long-term system logs and data within the application and design a plan for a permanent system upgrade rather than a temporary fix. Upload the plan to the application.', 'By filtering the system’s large volume of log data using the right analysis tools, identifies long-term chronic bottlenecks and, rather than applying patches to the system, designs a long-term capacity-enhancement plan and uploads this plan to the system.'),
  ('problem_solving', 4, 1, 10, 'To follow current literature and emerging technologies and adapt innovative and non- standard solution methods to the problem.', 'Explain how an innovative technology can be adapted to a specific problem by searching current papers and patent databases and upload this information to the system.', 'In situations where standard procedures are insufficient, successfully adapts a cutting- edge innovation (for example, AI) found in the digital patent or paper library into the simulation environment.'),
  ('problem_solving', 4, 2, 1, 'To provide guidance and direction to team members on systematic problem-solving techniques.', 'Create an interactive guide document (virtual tutorial) explaining problem-solving tools for lower-level (L1 or L2) trainee profiles. Upload this to the application.', 'transforms complex problem- solving tools into an interactive digital guide with the simplicity and accuracy that virtual users at the L1 or L2 levels can understand.'),
  ('problem_solving', 4, 2, 2, 'To lead the team in collaboratively developing a solution by facilitating group brainstorming sessions.', 'As a moderator, lead a virtual brainstorming session designed within the app, categorize the idea bubbles on the screen, and guide the team toward consensus.', 'During the virtual session she moderates, successfully groups the ideas that appear on the screen within a logical framework and, by encouraging passive virtual participants, guides the team toward the targeted, collaborative innovative solution.'),
  ('problem_solving', 4, 2, 3, 'To provide constructive feedback to less experienced interns or junior team members on problem diagnosis and resolution.', 'Reading diagnostic analysis reports from lower levels (L1 or L2) into the system via a digital rubric and writing constructive and helpful feedback.', 'Identifies technical errors in incoming diagnostic reports with an objective and keen eye using a checklist. Provides feedback that is non- confrontational, professional, constructive, and based entirely on technical arguments.'),
  ('problem_solving', 4, 2, 4, 'To document the stages of resolved problems and the lessons learned for the organization’s knowledge base.', 'Submit a digital report in "Lessons Learned" format for successfully closed cases to the organization''s knowledge base for approval.', 'Converts the technical experience gained from the crisis and the successful steps taken to resolve it into a structured “Lessons Learned” document that other engineers can easily find and apply using a search engine. Uploads this to the system.'),
  ('problem_solving', 4, 2, 5, 'To analyse existing inefficiencies in the problem-solving process and propose recommendations to accelerate the process or improve quality.', 'Identify inefficiencies in the team’s problem-solving steps using the system’s process map and highlight areas for optimization.', 'Provides a bird''s-eye view of the current operational process map used by the team. By pinpointing instances of resource waste, repetitive approvals, or unnecessary waiting steps, maps out concrete optimization paths.'),
  ('problem_solving', 4, 2, 6, 'To systematically monitor the results of solution implementation and conduct process improvement initiatives using the data obtained.', 'After implementing the solution, track real-time metrics from the field using the application dashboard and assign continuous improvement goals.', 'After the solution is deployed, it algorithmically analyses the real-time performance data displayed on the live- dashboard screen and sets new continuous improvement targets for the system to address any deviations.'),
  ('problem_solving', 4, 2, 7, 'To promote a culture of collaborative problem- solving by fostering effective communication among team members from diverse disciplines.', 'To break down complex technical information into a level that people with varying levels of expertise can understand by creating visuals and graphics, and upload these in the app.', 'Create visuals and graphics to present detailed engineering calculations in a format that people with varying levels of expertise can understand and implement them. In this way, to build a bridge of communication during virtual meetings.'),
  ('problem_solving', 4, 2, 8, 'To contribute to the conversion of successful solution strategies into standard operating procedures.', 'Using the “Procedure Designer Module” within the application, transform a successful solution strategy into a permanent and sustainable standard procedure that everyone will follow.', 'Transforms an innovative intervention that has achieved one-time success into a standardized, step-by-step operational guide that can be implemented on every shift, using the system’s procedure designer tool.'),
  ('problem_solving', 4, 2, 9, 'To design and advocate for systemic changes embedded within the process to prevent the recurrence of encountered errors.', 'Design an in-system error- prevention mechanism that will fundamentally prevent identified hardware or human errors and upload this mechanism to the application.', 'Logically constructs a hardware or software “Poka- Yoke (Error-Proofing)” circuit, designed with technical ingenuity, that will reduce the likelihood of chronic human or systematic errors observed in the system to zero.'),
  ('problem_solving', 4, 2, 10, 'To manage stakeholder expectations during the resolution of complex problems and professionally report outcomes to senior management.', 'Preparing and uploading a comprehensive professional “Management Report” that includes a cost-benefit analysis and technical progress and presenting it to virtual stakeholders.', 'Prepares a highly calibrated, data-driven, and persuasive professional Executive Report that balances the investment and profit expectations (ROI) of senior management with technical realities during the crisis resolution process, and uploads it to the system.'),
  ('communication', 1, 1, 1, 'Identify synchronous communication tools.', 'List the primary tools used for immediate team collaboration.', 'Intern accurately identifies tools like Slack or Microsoft Teams.'),
  ('communication', 1, 1, 2, 'Identify asynchronous communication channels.', 'Identify the appropriate channel for formal client updates.', 'Intern selects email as the primary asynchronous channel.'),
  ('communication', 1, 1, 3, 'Recognize meeting schedules.', 'Locate the time and virtual room for the daily team stand-up.', 'Intern attends the daily stand-up on time.'),
  ('communication', 1, 1, 4, 'Understand emergency contact protocols.', 'Find the emergency contact list for urgent technical issues.', 'Intern identifies the IT support hotline or on-call engineer.'),
  ('communication', 1, 1, 5, 'Identify client-facing portals.', 'Navigate to the external portal used for sharing files with clients.', 'Portal is located and login requirements are understood.'),
  ('communication', 1, 1, 6, 'Recognize organizational hierarchy in communication.', 'Identify the direct reporting line for internship queries.', 'Intern correctly names their assigned supervisor or mentor.'),
  ('communication', 1, 1, 7, 'Identify broad company announcements.', 'Locate the platform used for monthly all-hands updates.', 'Intern identifies the intranet portal or global email list.'),
  ('communication', 1, 1, 8, 'Understand departmental group chats.', 'Join the specific messaging channel for the engineering team.', 'Intern is actively part of the relevant group chat.'),
  ('communication', 1, 1, 9, 'Recognize physical notice boards.', 'Locate the health and safety notice board in the office/lab.', 'Intern confirms the location of statutory notices.'),
  ('communication', 1, 1, 10, 'Identify knowledge base repositories.', 'Find the internal wiki used for sharing standard operating procedures.', 'Wiki is bookmarked for future reference.'),
  ('communication', 1, 2, 1, 'Understand professional email etiquette.', 'Review past email threads to identify standard greeting and sign-off norms.', 'Intern describes the standard tone and structure used.'),
  ('communication', 1, 2, 2, 'Observe active listening in meetings.', 'Shadow a design review meeting and note how feedback is received.', 'Intern lists three ways participants acknowledge feedback constructively.'),
  ('communication', 1, 2, 3, 'Comprehend expected response times.', 'Review the policy on expected turnaround for internal messages.', 'Intern states the standard SLA for email and chat responses.'),
  ('communication', 1, 2, 4, 'Understand out-of- office protocols.', 'Observe how team members communicate planned absences.', 'Intern sets up a sample out- of-office auto-reply correctly.'),
  ('communication', 1, 2, 5, 'Recognize video conferencing norms.', 'Note the standard practices for camera usage and muting during calls.', 'Intern mutes their microphone when not speaking during the next call.'),
  ('communication', 1, 2, 6, 'Observe the use of technical jargon.', 'Compile a list of common acronyms used during team discussions.', 'List contains at least five accurate acronyms and their meanings.'),
  ('communication', 1, 2, 7, 'Understand meeting documentation expectations.', 'Review a set of meeting minutes distributed by the project manager.', 'Intern identifies action items and assigned owners in the document.'),
  ('communication', 1, 2, 8, 'Observe conflict de- escalation communication.', 'Review a case study or email thread showing a resolved technical disagreement.', 'Intern describes the professional language used to reach consensus.'),
  ('communication', 1, 2, 9, 'Understand status reporting norms.', 'Read through the weekly progress reports submitted by the team.', 'Intern identifies the structure: tasks completed, in progress, and blockers.'),
  ('communication', 1, 2, 10, 'Recognize inclusive language practices.', 'Review company guidelines on diversity and inclusive communication.', 'Intern adheres to inclusive language in all written drafts.'),
  ('communication', 2, 1, 1, 'Contribute to daily stand-ups.', 'Provide a clear 1-minute update on daily progress and blockers during the morning huddle.', 'Update is concise, relevant, and delivered confidently.'),
  ('communication', 2, 1, 2, 'Ask clarifying technical questions.', 'Formulate and ask a specific technical question during a design review meeting.', 'Question is clearly stated and demonstrates engagement with the material.'),
  ('communication', 2, 1, 3, 'Use instant messaging appropriately.', 'Send a direct message to a peer to coordinate a minor task handoff.', 'Message is professional in tone and provides all necessary context.'),
  ('communication', 2, 1, 4, 'Practice active listening skills.', 'Paraphrase a mentor''s instructions back to them to ensure accurate understanding.', 'Mentor confirms that the paraphrased instructions are correct.'),
  ('communication', 2, 1, 5, 'Provide constructive peer feedback.', 'Offer one piece of constructive, polite feedback during a peer''s presentation practice.', 'Feedback is specific, actionable, and delivered respectfully.'),
  ('communication', 2, 1, 6, 'Acknowledge receipt of instructions.', 'Reply promptly to a task assignment email confirming understanding and timelines.', 'Confirmation is sent within the expected organizational timeframe.'),
  ('communication', 2, 1, 7, 'Participate in brainstorming sessions.', 'Contribute at least two unique ideas during a team problem-solving workshop.', 'Ideas are communicated clearly and relate directly to the problem statement.'),
  ('communication', 2, 1, 8, 'Express concerns professionally.', 'Communicate a potential delay in task completion to the supervisor before the deadline.', 'Communication includes the reason for delay and a proposed new timeline.'),
  ('communication', 2, 1, 9, 'Engage with non- technical staff.', 'Explain a basic engineering requirement to a member of the administrative or HR team.', 'Explanation is jargon-free and easily understood by the recipient.'),
  ('communication', 2, 1, 10, 'Maintain professional body language.', 'Maintain appropriate eye contact and posture during a one-on-one performance review.', 'Non-verbal cues demonstrate attentiveness and professionalism.'),
  ('communication', 2, 2, 1, 'Draft professional internal emails.', 'Write an email to the IT department requesting software access, using standard formatting.', 'Email includes a clear subject line, polite request, and formal sign-off.'),
  ('communication', 2, 2, 2, 'Summarize meeting discussions.', 'Draft bullet-point minutes for a 30- minute team meeting and distribute to attendees.', 'Minutes accurately capture decisions made and outline next steps.'),
  ('communication', 2, 2, 3, 'Write clear task descriptions.', 'Document the steps taken to resolve a minor technical issue in the project tracker.', 'Description is sequential, logical, and easy for another engineer to follow.'),
  ('communication', 2, 2, 4, 'Formulate status update reports.', 'Draft a weekly end-of-week summary email detailing personal accomplishments and next week''s goals.', 'Report is structured correctly and free of grammatical errors.'),
  ('communication', 2, 2, 5, 'Compose professional chat messages.', 'Post a project update in the main team channel summarizing a reached milestone.', 'Message is enthusiastic yet professional, utilizing appropriate tagging (@).'),
  ('communication', 2, 2, 6, 'Structure technical queries.', 'Draft an email to a senior engineer outlining a problem and proposing a potential solution for review.', 'Email clearly separates the problem statement from the proposed solution.'),
  ('communication', 2, 2, 7, 'Proofread written communications.', 'Review and correct a draft technical memo for spelling, grammar, and tone before sending.', 'Final memo is error-free and maintains a professional tone.'),
  ('communication', 2, 2, 8, 'Write instructional documentation.', 'Draft a one-page ''How-To'' guide for operating a specific piece of lab equipment.', 'Guide is easy to read, uses bullet points, and includes safety warnings.'),
  ('communication', 2, 2, 9, 'Respond to internal inquiries.', 'Reply to an email from a colleague asking for data, providing the information clearly and concisely.', 'Response directly answers the question without unnecessary elaboration.'),
  ('communication', 2, 2, 10, 'Utilize templates effectively.', 'Populate a standard risk assessment form with relevant data for a new project phase.', 'Form is filled out completely, adhering strictly to the template''s constraints.'),
  ('communication', 3, 1, 1, 'Design effective visual aids.', 'Create a slide deck to support a 10- minute presentation on research findings.', 'Slides are visually clean, not text-heavy, and highlight key data points.'),
  ('communication', 3, 1, 2, 'Deliver technical presentations.', 'Present the results of a material testing cycle to the immediate project team.', 'Presentation is delivered smoothly, adhering to the allotted time limit.'),
  ('communication', 3, 1, 3, 'Adapt communication to the audience.', 'Explain the rationale behind a design change to both a senior engineer and an administrative manager.', 'Explanation is appropriately technical for the engineer and simplified for the manager.'),
  ('communication', 3, 1, 4, 'Handle Q&A sessions.', 'Respond to peer questions effectively following a brief technical presentation.', 'Answers are clear, direct, and admit when further research is needed.'),
  ('communication', 3, 1, 5, 'Utilize data storytelling.', 'Present a monthly expense report using charts to highlight trends rather than just raw numbers.', 'Data presentation clearly illustrates the core narrative or trend.'),
  ('communication', 3, 1, 6, 'Present project proposals.', 'Pitch a minor process improvement idea to the supervisor using a structured proposal format.', 'Pitch clearly defines the problem, solution, cost, and benefit.'),
  ('communication', 3, 1, 7, 'Communicate complex risks.', 'Verbally outline the potential risks associated with a new software implementation during a meeting.', 'Risks are communicated objectively without causing unnecessary alarm.'),
  ('communication', 3, 1, 8, 'Demonstrate software workflows.', 'Conduct a live demonstration of a newly developed CAD model to the design team.', 'Demonstration is easy to follow and highlights the model''s key features.'),
  ('communication', 3, 1, 9, 'Articulate design defenses.', 'Defend a specific material choice during a design review using data and logical reasoning.', 'Defense relies on facts and remains respectful of opposing viewpoints.'),
  ('communication', 3, 1, 10, 'Synthesize research findings.', 'Present a 5-minute summary of a recently published industry paper relevant to the team''s work.', 'Summary captures the paper''s core thesis and its practical application to the project.'),
  ('communication', 3, 2, 1, 'Draft meeting agendas.', 'Create and distribute an agenda for a small sub-team check-in meeting 24 hours in advance.', 'Agenda includes topics, time allocations, and required preparations.'),
  ('communication', 3, 2, 2, 'Moderate meeting pacing.', 'Lead a 15-minute stand-up, ensuring all members speak and the meeting ends on time.', 'Meeting stays on topic and concludes within the scheduled window.'),
  ('communication', 3, 2, 3, 'Facilitate brainstorming.', 'Guide a team brainstorming session to solve a minor logistical issue.', 'Facilitator encourages participation from all members and notes all ideas.'),
  ('communication', 3, 2, 4, 'Manage meeting interruptions.', 'Politely redirect the conversation when a meeting topic begins to drift off-agenda.', 'Redirection is handled professionally, keeping the meeting focused.'),
  ('communication', 3, 2, 5, 'Synthesize meeting outcomes.', 'Summarize the key decisions made at the end of a discussion before adjourning.', 'Summary accurately reflects the consensus reached by the group.'),
  ('communication', 3, 2, 6, 'Delegate action items.', 'Verbally confirm who is responsible for which task at the close of a planning meeting.', 'Action items are assigned clearly with agreed-upon deadlines.'),
  ('communication', 3, 2, 7, 'Handle technical disagreements.', 'Mediate a brief debate between two peers regarding a design choice to reach a compromise.', 'Mediation remains neutral and focuses on project goals over personal opinions.'),
  ('communication', 3, 2, 8, 'Facilitate virtual meetings.', 'Host a video conference call, managing screen sharing and participant muting effectively.', 'Call runs smoothly without technical interruptions caused by the host.'),
  ('communication', 3, 2, 9, 'Encourage quiet participants.', 'Directly, yet politely, ask for input from a team member who hasn''t spoken during a review.', 'Action successfully brings diverse viewpoints into the discussion.'),
  ('communication', 3, 2, 10, 'Follow up on meeting deliverables.', 'Send a follow-up email two days after a meeting to check on the status of delegated tasks.', 'Email serves as a polite reminder and offers assistance if needed.'),
  ('communication', 4, 1, 1, 'Draft client-facing emails.', 'Draft an email updating a supplier on a delayed shipment, for supervisor review.', 'Draft requires minimal edits and adopts an appropriate external tone.'),
  ('communication', 4, 1, 2, 'Participate in client calls.', 'Introduce oneself and provide a brief status update during a scheduled client video call.', 'Update is professional, reassuring, and avoids overpromising.'),
  ('communication', 4, 1, 3, 'Prepare external reports.', 'Compile a monthly progress report formatted specifically for a client''s review.', 'Report meets all external branding and formatting guidelines.'),
  ('communication', 4, 1, 4, 'Handle external inquiries.', 'Respond to a basic technical question from a vendor regarding a part specification.', 'Response is accurate and represents the company professionally.'),
  ('communication', 4, 1, 5, 'Translate technical concepts for clients.', 'Explain a complex engineering constraint to a non-technical client during a meeting.', 'Client confirms understanding without feeling overwhelmed by jargon.'),
  ('communication', 4, 1, 6, 'Manage client expectations.', 'Draft a communication politely explaining why a requested feature falls outside the project scope.', 'Communication is firm, polite, and references the original contract/scope.'),
  ('communication', 4, 1, 7, 'Conduct site visit communications.', 'Interact professionally with contractors while collecting data during an external site visit.', 'Interactions are respectful and adhere to site protocols.'),
  ('communication', 4, 1, 8, 'Assist with proposal writing.', 'Draft a section of a project proposal intended for a potential new client.', 'Section is persuasive, technically sound, and aligns with the proposal''s overall voice.'),
  ('communication', 4, 1, 9, 'Prepare presentation materials for stakeholders.', 'Create a polished slide deck for a project handover meeting with the client.', 'Deck is high-quality, comprehensive, and tailored to stakeholder interests.'),
  ('communication', 4, 1, 10, 'Follow up post- engagement.', 'Draft a ''Thank You'' and next-steps email following an initial meeting with a new vendor.', 'Email builds rapport and clearly outlines the agreed- upon next steps.'),
  ('communication', 4, 2, 1, 'Receive critical feedback constructively.', 'Listen to critical feedback on a failed task during a 1-on-1 and outline a plan for improvement.', 'Feedback is received without defensiveness and applied to future work.'),
  ('communication', 4, 2, 2, 'Deliver difficult news professionally.', 'Inform the project team of a significant technical failure that will delay the schedule.', 'News is delivered promptly, objectively, and accompanied by a mitigation plan.'),
  ('communication', 4, 2, 3, 'Navigate resource negotiations.', 'Request additional lab time from a lab manager whose schedule is already fully booked.', 'Request is made politely, offering flexibility and demonstrating valid need.'),
  ('communication', 4, 2, 4, 'De-escalate tense communications.', 'Draft a calming, objective response to an overly aggressive email from a frustrated colleague.', 'Response sticks to facts, avoids emotional escalation, and proposes a meeting to resolve.'),
  ('communication', 4, 2, 5, 'Advocate for technical solutions.', 'Argue for the adoption of a specific software tool despite pushback from team members.', 'Argument is persistent but respectful, relying on cost- benefit data.'),
  ('communication', 4, 2, 6, 'Manage scope creep discussions.', 'Politely decline a peer''s request to add an extra feature to a nearly completed model.', 'Declination cites timeline constraints and prioritizes project completion.'),
  ('communication', 4, 2, 7, 'Communicate safety violations.', 'Report an observed safety protocol breach to the supervisor formally and objectively.', 'Report is factual, timely, and free of personal accusations.'),
  ('communication', 4, 2, 8, 'Handle miscommunication fallouts.', 'Apologize for and correct a miscommunicated instruction that led to a minor error.', 'Apology takes ownership of the mistake and clarifies the correct procedure.'),
  ('communication', 4, 2, 9, 'Provide upward feedback.', 'Constructively communicate to a supervisor that a given deadline is unachievable.', 'Communication provides evidence of the workload and suggests a realistic alternative.'),
  ('communication', 4, 2, 10, 'Document dispute resolutions.', 'Write a formal email summarizing the agreed resolution following a conflict regarding task ownership.', 'Summary is agreed upon by all parties and prevents future misunderstandings.'),
  ('ethics', 1, 1, 1, 'Learn what safety rules and attendance expectations exist in the host company.', 'Read through the company safety handbook from first da. Write down the main rules and required arrival times. Log the checklist in EngineerTrack and share it with your mentor by end of day.', 'Mentor reviews the checklist in EngineerTrack. At least 8 rules are correctly noted and the attendance times are accurate.'),
  ('ethics', 1, 1, 2, 'Understand why arrival on time matters in a real engineering workplace.', 'Record your arrival and departure times daily in EngineerTrack for the first two weeks. Submit the log to your supervisor each Friday through the app.', 'Supervisor checks the log in EngineerTrack. No days are missing and times match the actual attendance record.'),
  ('ethics', 1, 1, 3, 'Know what may happen when safety rules are broken at workplace.', 'Attend the safety induction. Afterwards write a one-page reflection in EngineerTrack identifying three consequences of non-compliance based on what was discussed.', 'The reflection names three realistic consequences that match what was covered in the induction, confirmed by the supervisor in the app.'),
  ('ethics', 1, 1, 4, 'Tell the difference between safety equipment that is required and guidance that is only recommended.', 'Watch a senior engineer do the daily safety check. Record each piece of PPE in EngineerTrack, marking each as required or optional.', 'Supervisor checks the list in EngineerTrack. Every item is correctly marked and nothing important is missing.'),
  ('ethics', 1, 1, 5, 'Know the steps to follow when you spot a hazard at work.', 'Spend a morning with the health and safety officer. Log every step of the hazard-reporting procedure in EngineerTrack in the order they were demonstrated.', 'The logged steps match the official reporting procedure. All steps are present and in the right order, verified by the supervisor.'),
  ('ethics', 1, 1, 6, 'Notice what professional behaviour looks like day to day in an engineering office.', 'During your first week, log three examples of professional responsibility shown by colleagues in EngineerTrack. Add a short note for each explaining why it matters.', 'Supervisor reads the three entries. Each one is a real, concrete example and the explanation makes sense.'),
  ('ethics', 1, 1, 7, 'Get a basic idea of what sustainability means in everyday work life.', 'Sit in on one team meeting where sustainability comes up. Log at least two specific practices mentioned by the team in EngineerTrack.', 'The logged notes name two practices clearly. A short comment is added on what each one achieves in terms of reducing impact.'),
  ('ethics', 1, 1, 8, 'Remember the emergency exit procedure for your work area.', 'Take part in a fire drill. Right after it ends, log every step from the alarm to the all-clear in EngineerTrack from memory.', 'All key steps are logged in the right order in EngineerTrack. No reference materials were used, confirmed by supervisor.'),
  ('ethics', 1, 1, 9, 'Find out who in the organisation is responsible for safety and ethics.', 'Using the company organisation chart, identify at least three people responsible for safety or ethics. Log their names and roles in EngineerTrack.', 'Three people correctly identified with accurate job titles, verified by supervisor through the app.'),
  ('ethics', 1, 1, 10, 'See the connection between showing up on time and how the team works.', 'Talk to one supervisor or experienced colleague about punctuality. Log a 150-word summary of the conversation in EngineerTrack and submit it to your mentor.', 'The summary reflects what the colleague said, includes one concrete example, and was submitted on time as recorded in EngineerTrack.'),
  ('ethics', 1, 2, 1, 'Spot the ethical rules and standards that apply to the current project.', 'Go through the project brief and related documents. Log every ethical guideline, code of conduct reference, or compliance requirement you find in EngineerTrack.', 'At least three ethical references correctly identified. For each one, a one-sentence note explains why it matters, visible in EngineerTrack for supervisor review.'),
  ('ethics', 1, 2, 2, 'Notice when and how sustainability goals show up in an active project.', 'Attend a project meeting. Take notes focused on sustainability targets or commitments. Log at least two in EngineerTrack with a brief explanation of how the team is working towards each.', 'Notes contain at least two sustainability goals logged in EngineerTrack. Supervising engineer confirms accuracy through the app.'),
  ('ethics', 1, 2, 3, 'Understand the difference between what engineers must do ethically and what is just good practice.', 'Read part of a relevant engineering code of ethics. Create a two-column table in EngineerTrack: one column for obligatory rules, one for recommended practices. Add at least five entries.', 'Table has five or more entries correctly placed. Each entry has a short reason why it belongs there, reviewable by mentor in EngineerTrack.'),
  ('ethics', 1, 2, 4, 'Learn which sustainability practices are used in day-to-day project work.', 'Observe how materials and waste are handled on the current project. Log descriptions of three specific practices in EngineerTrack.', 'Three practices described clearly in EngineerTrack. Each one linked to a sustainability principle. Submitted by agreed deadline as tracked in the app.'),
  ('ethics', 1, 2, 5, 'Recognise when a personal interest might get in the way of doing the right thing professionally.', 'Read a case study about an engineering ethics dilemma. Log a short paragraph in EngineerTrack identifying the conflict and the parties affected.', 'Paragraph correctly names the conflict and at least two affected parties. The explanation shows understanding of why it is a problem, reviewed by supervisor.'),
  ('ethics', 1, 2, 6, 'Know what confidentiality and data privacy mean for someone in an internship.', 'Read the organisation''s data privacy policy or NDA. Write a plain one- page summary of key obligations and upload it to EngineerTrack.', 'Summary covers the main obligations correctly. Written in simple language. Mentor reviews and approves it in EngineerTrack.'),
  ('ethics', 1, 2, 7, 'See how environmental concerns shape decisions in an engineering project.', 'Sit in on or read notes from an environmental review meeting. Log three decisions that were shaped by environmental factors in EngineerTrack.', 'Three decisions are logged. Each includes a note on which environmental concern drove it, confirmed by supervising engineer.'),
  ('ethics', 1, 2, 8, 'Understand why getting data right matters from an ethical point of view.', 'Join a data quality review session. Log the verification steps used by the team in EngineerTrack and add a note on what happens if mistakes are made.', 'Steps logged in the right order. One consequence of data errors is noted, showing the intern understood why accuracy matters, reviewed by supervisor.'),
  ('ethics', 1, 2, 9, 'Find out if there are more sustainable options for the materials being used in the project.', 'Make a list of materials or resources used in your current task in EngineerTrack. Next to each, note whether a more sustainable option exists based on observation or brief research.', 'At least five items listed. A sustainability note must be given for each. At least one outside source cited, visible in EngineerTrack.'),
  ('ethics', 1, 2, 10, 'Get a basic understanding of corporate social responsibility and how it relates to the host company.', 'Find the company''s CSR or sustainability report. Prepare five key points and log them in EngineerTrack, highlighting two relevant to engineering work. Present them to your mentor.', 'Five points logged and presented. Two engineering- relevant points clearly highlighted. Intern answers at least two follow-up questions correctly, outcome logged by mentor.'),
  ('ethics', 2, 1, 1, 'Plan your work for the week and get tasks done within the times agreed with your supervisor.', 'At the start of every week, create a task plan in EngineerTrack listing all assigned tasks, estimated durations, and agreed deadlines. Update status each day.', 'Plan updated every week in EngineerTrack. At least 80% of tasks completed by their deadlines, confirmed by supervisor through the app.'),
  ('ethics', 2, 1, 2, 'Follow safety checks every time you start a new task, not just the ones that seem risky.', 'Before starting any task, complete the pre-task safety checklist in EngineerTrack and submit it to your supervisor before beginning work.', 'A checklist submitted in EngineerTrack before every task. No items left blank or incorrect. Supervisor verifies through the app.'),
  ('ethics', 2, 1, 3, 'Decide which task to do first when you have several tasks to do in the same time.', 'When given three or more tasks at the same time, create a priority matrix in EngineerTrack using urgent versus important as your axes. Share it with your supervisor before starting.', 'Priority matrix produced in EngineerTrack for each multi-task situation. Supervisor agrees with the proposed order in at least 80% of cases. Tasks completed in that order.'),
  ('ethics', 2, 1, 4, 'Keep your supervisor informed about how work is going and flag problems early on.', 'Send a short daily status update through EngineerTrack every working day, three to five points covering what you did and any risk of delay.', 'Updates sent on at least 90% of working days in EngineerTrack. Accurate content. Any delay risk is flagged at least one day before the deadline, confirmed by supervisor.'),
  ('ethics', 2, 1, 5, 'Follow a Standard Operating Procedure properly when carrying out a routine task.', 'Pick one routine task with an SOP. Follow it step by step and log each completed step in EngineerTrack as you go.', 'Task log in EngineerTrack shows every step completed in the right order. Nothing skipped. Supervisor checks against the official SOP.'),
  ('ethics', 2, 1, 6, 'Get better at estimating how long tasks will actually take.', 'Before each new task, log your time estimate and reasoning in EngineerTrack. When finished, log the actual time taken and note the difference.', 'Done for at least four tasks in EngineerTrack. Estimates within 20% of actual time on at least three occasions. Notes show progressive learning from the gaps.'),
  ('ethics', 2, 1, 7, 'Spot problems with quality during routine work and report them straight away.', 'Use the quality checklist in EngineerTrack while doing each task. If something falls short of the standard, log it and notify your supervisor through the app the same day.', 'All significant quality problems reported within two hours via EngineerTrack. Written record accurate. Supervisor confirms through the app.'),
  ('ethics', 2, 1, 8, 'Handle sensitive project information carefully and keep it confidential.', 'For any task involving confidential data, add a note in EngineerTrack confirming which data-handling protocol was followed.', 'Every relevant task entry in EngineerTrack includes this note. Supervisor confirms no breaches occurred during the supervised period.'),
  ('ethics', 2, 1, 9, 'Write up what happened after each task is finished.', 'When a task is done, complete the outcome record in EngineerTrack: task description, time taken, result achieved, and any problems encountered.', 'Outcome record submitted in EngineerTrack for every task. All fields filled. Submitted within one hour of finishing. Supervisor verifies.'),
  ('ethics', 2, 1, 10, 'Look back at your week and work out what you could do differently next time.', 'Every Friday, complete the weekly self-evaluation form in EngineerTrack: tasks planned versus done, reasons for anything not finished, and one improvement for next week. Discuss with supervisor.', 'Form submitted every Friday in EngineerTrack without being reminded. Supervisor confirms the reflection is honest and the improvement point is genuine.'),
  ('ethics', 2, 2, 1, 'Apply the right industry standard when working on any task you are given.', 'Before starting a task, find the applicable standard, note its number and key requirements in EngineerTrack, and complete the task in compliance with it.', 'Correct standard identified and logged for at least 80% of tasks in EngineerTrack. Supervisor confirms work met the standard''s requirements in each case.'),
  ('ethics', 2, 2, 2, 'Write emails, notes, and reports in a way that is professional and appropriate for an engineering workplace.', 'Draft all task-related communications professionally. Upload the first three to EngineerTrack for mentor review before sending.', 'Mentor finds no significant issues with the first three in EngineerTrack. Later communications on time with no concerns from the supervisor.'),
  ('ethics', 2, 2, 3, 'See how professional codes of conduct shape real decisions during the working week.', 'Read the relevant professional code of conduct. Each day, log one short note in EngineerTrack on how something in the code affected a decision you made.', 'At least four notes logged over the week in EngineerTrack. Each links a specific code provision to a specific decision. Supervisor validates.'),
  ('ethics', 2, 2, 4, 'Make sure data is recorded correctly by having someone else check it.', 'For every piece of data you record, ask a colleague or supervisor to check it. Log who checked it and the result in EngineerTrack.', 'Every data entry has a second check recorded in EngineerTrack. No entries left unchecked. Supervisor confirms at end of each week.'),
  ('ethics', 2, 2, 5, 'Choose materials or methods that are better for the environment when you have a choice.', 'When you have two or more options for a material or method, use the decision matrix in EngineerTrack to score each against environmental criteria. Log the choice and the reason.', 'Decision matrix completed in EngineerTrack for at least two choices. Supervisor agrees the selection is environmentally sound.'),
  ('ethics', 2, 2, 6, 'Do a safety check before every new type of task, even routine ones.', 'Fill in a brief written risk assessment in EngineerTrack before each new type of task. Submit to supervisor through the app before starting.', 'Risk assessment submitted in EngineerTrack before every new task type. None missing or incomplete. Supervisor confirms.'),
  ('ethics', 2, 2, 7, 'Know when something is beyond what you are allowed to decide on your own and ask for help.', 'If a task requires a decision beyond your current scope, log the situation in EngineerTrack and notify your supervisor through the app immediately before proceeding.', 'At least two such situations correctly identified and escalated in EngineerTrack. Supervisor confirms no unauthorised decisions were made.'),
  ('ethics', 2, 2, 8, 'Deliver your work to colleagues on time and let them know when it is ready.', 'Track every output owed to a team member in EngineerTrack. When you deliver it, log a delivery confirmation in the app straight away.', '90% of outputs delivered on time. Delivery confirmation logged in EngineerTrack in 100% of cases. Verified by supervisor and team member records.'),
  ('ethics', 2, 2, 9, 'Stay within the boundaries of what you are supposed to be doing each week.', 'At the start of each week, confirm your scope of work with your supervisor in EngineerTrack. Flag any request that appears to fall outside it through the app.', 'Scope confirmed in EngineerTrack for at least 90% of weeks. Any out-of- scope requests flagged. Supervisor confirms.'),
  ('ethics', 2, 2, 10, 'Check your own work against quality standards before handing it in.', 'Before submitting any output, complete the self-audit checklist in EngineerTrack and attach it to the submission in the app.', 'Checklist attached to every submission in EngineerTrack. Supervisor''s own check finds the intern correctly spotted any gaps in at least 80% of submissions.'),
  ('ethics', 3, 1, 1, 'Build a personal system for managing your time across several tasks at once, without needing your supervisor to chase you.', 'At the start of each two-week period, create your own work plan in EngineerTrack listing all tasks, durations, dependencies, and deadlines. Share it with your supervisor before they ask.', 'Plan shared in EngineerTrack at the start of every cycle without a reminder. Supervisor says it is realistic. At least 90% of tasks finished on time.'),
  ('ethics', 3, 1, 2, 'Figure out on your own what caused a deadline to be at risk and fix it.', 'When a deadline is in danger at least 48 hours before it is due, log a root-cause analysis and recovery plan in EngineerTrack. Put the plan into action and report the outcome through the app.', 'Deadline risks spotted at least 48 hours early in at least 80% of situations without supervisor prompting. Recovery plan logged in EngineerTrack and confirmed as appropriate.'),
  ('ethics', 3, 1, 3, 'Take full responsibility for the commitments you make to colleagues and others.', 'Keep a running commitment log in EngineerTrack of every timing promise made to any team member or stakeholder. Review it daily and follow up on anything coming due soon.', 'Log updated every day in EngineerTrack. No commitment missed without advance notice. Supervisor confirms.'),
  ('ethics', 3, 1, 4, 'Think ahead about which tasks might take longer than planned and adjust before it becomes a problem.', 'At the start of each week, rate every task as High, Medium, or Low risk in EngineerTrack based on complexity. Allocate extra time in the plan to high-risk ones.', 'Risk-rated plan produced independently in EngineerTrack each week. Supervisor agrees ratings make sense in at least 85% of plans. Actual outcomes confirm the ratings.'),
  ('ethics', 3, 1, 5, 'Show up on time every day and maintain that habit throughout the advanced phase.', 'Keep a clean attendance record logged in EngineerTrack for the whole advanced phase. If something unexpected happens, notify your supervisor and affected colleagues through the app as early as possible.', 'No unexplained late arrivals or absences in EngineerTrack during the advanced phase. Any exceptions communicated early. Supervisor confirms.'),
  ('ethics', 3, 1, 6, 'Reflect honestly on how well your time management is working and make real changes.', 'At the end of each two-week cycle, log a short review in EngineerTrack: what worked, what did not, and one specific thing you will do differently. Share key points with your supervisor.', 'Review logged in EngineerTrack at end of every cycle. Supervisor confirms a real improvement is applied in the next cycle across at least three consecutive cycles.'),
  ('ethics', 3, 1, 7, 'Build sustainability checks into your planning when tasks involve physical resources.', 'When planning any task that uses materials, equipment, or energy, add a sustainability check step in EngineerTrack with time allocated for verifying responsible resource use.', 'Sustainability check step included in the plan for every relevant task in EngineerTrack. Supervisor confirms checks are genuine and at least one real improvement results.'),
  ('ethics', 3, 1, 8, 'Handle unexpected extra tasks without letting your existing commitments slip.', 'When an unplanned task is assigned, assess its impact on your current plan independently and log the re-prioritisation decision in EngineerTrack. Negotiate revised timelines if needed through the app.', 'Unplanned tasks handled independently in at least 80% of cases. Existing commitments met or renegotiated in advance in 100% of cases. Supervisor confirms in EngineerTrack.'),
  ('ethics', 3, 1, 9, 'Report your progress honestly each week without overstating what has been done.', 'Every Friday, submit a weekly progress report in EngineerTrack, clearly separating tasks done, in progress, and not started. Give real reasons for anything incomplete.', 'Reports submitted every Friday in EngineerTrack without prompting. Spot- check finds no difference between reported and actual status in at least 90% of reports.'),
  ('ethics', 3, 1, 10, 'Have a clear plan ready for when several urgent deadlines land at the same time.', 'Whenever two or more high- priority deadlines fall within 24 hours of each other, log a contingency plan in EngineerTrack before that point. Include escalation path and resource needs. Share with supervisor.', 'Contingency plan logged in EngineerTrack for every such situation without being asked. Supervisor rates it adequate or better in at least 80% of cases. Outcomes confirm it worked.'),
  ('ethics', 3, 2, 1, 'Use a proper ethical reasoning approach when a technical decision involves a moral dimension.', 'When a technical choice has an ethical side, log your reasoning in EngineerTrack: framework used, options considered, stakeholders affected, decision made, and why. Share with supervisor.', 'At least three such records logged in EngineerTrack during the advanced phase. Supervisor confirms reasoning is sound, stakeholders correctly identified, and decision is ethically justifiable.'),
  ('ethics', 3, 2, 2, 'Compare technical options on environmental grounds and choose the one with the smallest footprint.', 'When you have two or more ways to solve a technical problem, log a comparison in EngineerTrack covering energy use, material waste, and lifecycle impact. Record choice and rationale.', 'Comparison logged in EngineerTrack for at least two choices. Supervisor confirms method is sound and option chosen is most sustainable among those feasible.'),
  ('ethics', 3, 2, 3, 'Take personal responsibility for the quality of your technical work without waiting for someone else to check it.', 'Before submitting any technical output, audit it against the relevant standard. Log a signed self- declaration in EngineerTrack confirming it meets requirements and attach it to the submission.', 'Signed declaration attached to every technical submission in EngineerTrack. Supervisor''s spot-check finds no quality failures in at least 85% of reviewed submissions.'),
  ('ethics', 3, 2, 4, 'Think about how a technical solution might affect different groups of people.', 'For one assigned technical task, research how the solution could affect different users. Log two social sustainability considerations in EngineerTrack and explain how each influenced your approach.', 'Two social sustainability points logged in EngineerTrack for the task. Supervisor confirms they are genuine, relevant, and actually influenced the technical decision.'),
  ('ethics', 3, 2, 5, 'Resolve tensions between getting things done quickly and doing them responsibly.', 'When a request pushes you to cut corners on a professional standard, log the conflict, your decision, and the outcome in EngineerTrack. Share with supervisor without being asked.', 'At least one such situation documented in EngineerTrack during the advanced phase. Supervisor confirms the resolution prioritised professional responsibility appropriately.'),
  ('ethics', 3, 2, 6, 'Be open about the limits and uncertainties of your technical work.', 'In every technical output, add a limitations and uncertainties section. Log it in EngineerTrack naming assumptions made, data gaps, and anything that could affect reliability.', 'This section appears in every technical output in EngineerTrack. Supervisor confirms it is honest and complete. No significant risks are played down.'),
  ('ethics', 3, 2, 7, 'Apply circular economy thinking when choosing materials or designing a process step.', 'When selecting materials or planning a process, complete the circular economy checklist in EngineerTrack covering reduce, reuse, recycle, and recover. Attach it to the technical output.', 'Checklist completed in EngineerTrack for at least two decisions. Supervisor confirms it is correctly applied and the choices made reduce waste or resource use.'),
  ('ethics', 3, 2, 8, 'Stand firm on quality and safety when someone pressures you to cut corners.', 'If you receive a request to skip a quality or safety step, log what was asked, what you said, and the outcome in EngineerTrack. Share the record with your supervisor.', 'Every such request refused or escalated. Records clear and accurate in EngineerTrack. Supervisor confirms the response was professional and appropriate.'),
  ('ethics', 3, 2, 9, 'Use digital or automated tools carefully and check their outputs.', 'Each time you use an automated or digital tool in technical work, log an entry in EngineerTrack: tool name, task it supported, how you verified the result, any limitations noticed.', 'Entry logged in EngineerTrack for every instance of automated tool use. Supervisor confirms verification steps described and intern shows awareness of limitations in at least 80% of entries.'),
  ('ethics', 3, 2, 10, 'Write your own professional ethics code based on real internship experience.', 'Draft a one-page personal ethics code with at least five principles grounded in real situations from the internship. Upload it to EngineerTrack and present each principle briefly to your supervisor.', 'Ethics code has at least five principles in EngineerTrack. Each grounded in a real experience. Supervisor confirms it reflects genuine thinking rather than generic statements.'),
  ('ethics', 4, 1, 1, 'Build and maintain a risk register that catches schedule problems before they turn into delays.', 'Set up a risk register in EngineerTrack for all assigned project tasks. Update it every week with new risks, probability ratings, and mitigation actions. Share with the team through the app.', 'Register updated on time every week in EngineerTrack. Supervisor confirms at least 60% of delays that actually occur were already in the register before they happened.'),
  ('ethics', 4, 1, 2, 'Use critical path analysis to see where a project could fall behind and prevent it.', 'For one project task running longer than a week, map the critical path and log it in EngineerTrack. Identify float points and use them to absorb disruption without losing the final deadline.', 'Critical path and float points correctly identified in EngineerTrack. Supervisor confirms accuracy. Final deadline met despite at least one disruption absorbed using the buffer.'),
  ('ethics', 4, 1, 3, 'Tell everyone affected by a schedule change before they have to ask.', 'When the schedule changes for any reason, log a brief notification in EngineerTrack and send it to all affected people within two hours of making the decision.', 'Notification sent within two hours through EngineerTrack for every schedule change. Supervisor confirms no one was surprised by a change during the expert phase.'),
  ('ethics', 4, 1, 4, 'Work out how a delay in one task will ripple through the rest of the project.', 'When a delay happens, log a cascade analysis in EngineerTrack independently. List every dependent task affected, the number of days impacted, and a recovery plan.', 'Analysis in EngineerTrack correctly identifies all tasks affected directly and indirectly. Delay quantified in days for each. Supervisor rates the recovery plan as feasible.'),
  ('ethics', 4, 1, 5, 'Prepare a backup plan for when key resources or people suddenly become unavailable.', 'For one major task, write a contingency schedule in EngineerTrack setting out alternative steps and resource options if something falls through. Present to supervisor before any problem arises.', 'Contingency schedule in EngineerTrack covers at least two realistic disruption scenarios with workable alternatives. Supervisor rates it feasible and detailed. Presented before any actual disruption.'),
  ('ethics', 4, 1, 6, 'Estimate task durations more accurately by accounting for best, worst, and most likely scenarios.', 'For every task over two hours, log three-point estimates in EngineerTrack: optimistic, most likely, and pessimistic. At task completion, compare actual time to the range and log the outcome.', 'Three-point estimates logged in EngineerTrack for every qualifying task. Actual times fall within the estimated range in at least 85% of cases during the expert phase.'),
  ('ethics', 4, 1, 7, 'Build environmental thinking into how you schedule project work.', 'When building or revising the schedule in EngineerTrack, identify at least one decision that reduces environmental impact. Log the reasoning and estimated or actual environmental benefit.', 'At least two sustainability- motivated scheduling decisions logged in EngineerTrack during the expert phase. Supervisor confirms they are logical, achievable, and show a measurable benefit.'),
  ('ethics', 4, 1, 8, 'Help less experienced colleagues manage time and communicate delays.', 'Organise a 30-minute session for fellow interns on proactive schedule management. Log the session plan and attendance in EngineerTrack. Prepare a one-page reference guide and upload it to the app.', 'Session logged and delivered on time in EngineerTrack. Guide judged clear and accurate by supervisor. At least one participant confirms they found it useful, outcome logged in the app.'),
  ('ethics', 4, 1, 9, 'Identify a weakness in how the team manages schedules and suggest a specific fix.', 'After a significant project phase, write a process improvement proposal in EngineerTrack: one scheduling problem observed and a specific change to fix it. Present to supervisor through the app.', 'Proposal in EngineerTrack identifies a real problem confirmed by supervisor. Fix is specific and workable. Supervisor rates it as adding value to how the team operates.'),
  ('ethics', 4, 1, 10, 'Keep quality standards in place even when the timeline is under pressure.', 'When working to a tight deadline, log in EngineerTrack which quality steps you kept and any formally agreed to defer, with a reason for each deferral. Submit to supervisor through the app.', 'Record submitted in EngineerTrack for every compressed-timeline situation. Supervisor confirms no quality steps were quietly dropped. All deferrals formally agreed and documented in the app.'),
  ('ethics', 4, 2, 1, 'Own a deliverable from start to finish without waiting to be told what to do at each step.', 'Take one major deliverable and manage the whole lifecycle in EngineerTrack: scope, plan, execution, quality check, and delivery. Log every key decision made along the way.', 'Deliverable handed over on time and meets quality requirements, confirmed by supervisor in EngineerTrack. Log shows the intern drove the process independently from start to finish.'),
  ('ethics', 4, 2, 2, 'Raise ethical concerns in the team when you spot them during project work.', 'When you identify an ethical issue, log it in EngineerTrack and raise it professionally with the relevant colleague or in a team setting. Record what happened and the outcome.', 'At least one ethical issue raised and logged in EngineerTrack during the expert phase. Supervisor confirms it was handled professionally and the outcome documented accurately.'),
  ('ethics', 4, 2, 3, 'Find a real sustainability problem in the team''s work and do something about it.', 'Identify a specific inefficiency that wastes resources or energy. Log an improvement proposal in EngineerTrack. With supervisor approval, implement it and document the outcome in the app.', 'Genuine inefficiency found and addressed. Improvement documented in EngineerTrack. Supervisor rates the initiative as showing expert-level ownership and confirms the improvement is real.'),
  ('ethics', 4, 2, 4, 'Create something useful on ethics or sustainability that the team can keep using after you leave.', 'Research the topic and produce a practical written resource for the team, such as a one-page ethics decision guide or sustainability checklist. Upload it to EngineerTrack and present it to the team.', 'Resource uploaded to EngineerTrack before the end of the expert phase. At least two team members confirm it is useful. Supervisor rates it as accurate, practical, and ready to use independently.'),
  ('ethics', 4, 2, 5, 'Honestly assess your own performance on responsibility and ethics across the whole internship.', 'Write a self-assessment of at least two pages covering the full internship period. Upload it to EngineerTrack. Include what went well, where you fell short, and three specific professional development commitments.', 'Report uploaded to EngineerTrack on time and covers the full period with real examples. Supervisor confirms it is neither overstated nor too modest. The three commitments are specific and realistic.'),
  ('ethics', 4, 2, 6, 'Show colleagues what can go wrong when ethical standards are ignored, using a real example.', 'Find one documented engineering ethics failure. Log a five-minute case-study presentation in EngineerTrack and deliver it to the team, linking the failure to long- term reputational and commercial consequences.', 'Presentation logged and delivered with at least one supervisor or team member present. Analysis of failure and consequences is accurate. Supervisor rates it as insightful and professionally delivered.'),
  ('ethics', 4, 2, 7, 'Apply lifecycle thinking to how you design or plan a key piece of work.', 'For one important deliverable, map out environmental impact at each lifecycle stage in EngineerTrack: raw materials, production, use, and end of life. Log how design choices kept the total impact low.', 'Lifecycle document logged in EngineerTrack covering all four stages. Supervisor confirms the analysis is accurate and at least two design choices were genuinely shaped by lifecycle considerations.'),
  ('ethics', 4, 2, 8, 'Notice when colleagues are acting responsibly and make sure that gets recognised.', 'Each week, log at least one example of a colleague showing strong professional responsibility or good sustainability practice in EngineerTrack. With supervisor approval, share anonymised highlights with the team.', 'Log maintained every week of the expert phase in EngineerTrack. Supervisor confirms examples are genuine. Anonymised sharing done at least twice and received positively by at least one person.'),
  ('ethics', 4, 2, 9, 'Work through a difficult situation where commercial pressure and professional responsibility pull in opposite directions.', 'When you face a real stakeholder conflict, log a stakeholder analysis and ethical resolution proposal in EngineerTrack. Present the recommended course of action with justification grounded in ethics principles.', 'Analysis in EngineerTrack names all key stakeholders and interests correctly. Proposed resolution grounded in at least one named ethics principle. Supervisor rates reasoning as nuanced and professionally sound.'),
  ('ethics', 4, 2, 10, 'Leave the host organisation something genuinely useful that they will still be using after you are gone.', 'Design and produce one lasting contribution to the organisation''s ethics or sustainability practice: an updated checklist, a training activity, or a reusable framework. Upload to EngineerTrack and get supervisor sign-off.', 'Contribution uploaded to EngineerTrack and formally signed off by supervisor before the internship ends. Judged as immediately usable. Supervisor confirms it addresses a real need and required the intern''s initiative to exist.'),
  ('documentation', 1, 1, 1, '1.1.1. To identify the main documentation standards used in the workplace.', 'Review the organisation’s basic documentation rules, templates, or reporting guidelines and record at least three relevant standards in the platform log.', 'Correctly identifies at least three documentation rules or standards used by the organisation and records them clearly in the digital log.'),
  ('documentation', 1, 1, 2, '1.1.2. To recognize the purpose of standard templates.', 'Locate one standard template used for technical reports, logs, or task records and upload an annotated blank template, outline, or short summary of its structure.', 'Explains the purpose of the selected template, identifies its main sections, and submits suitable digital evidence.'),
  ('documentation', 1, 1, 3, '1.1.3. To understand basic reporting expectations for interns.', 'Ask the mentor which technical information must be reported during daily or weekly internship activities and upload a short reporting expectations note.', 'Correctly lists the expected reporting frequency, format, recipient, and main content to be reported.'),
  ('documentation', 1, 1, 4, '1.1.4. To identify where technical documents are stored.', 'Navigate the shared folder, project platform, internal wiki, or document repository used by the team and submit a short note or non- confidential screenshot showing the repository type.', 'Locates the correct repository and identifies where current project documents are stored, without exposing confidential file names or contents.'),
  ('documentation', 1, 1, 5, '1.1.5. To recognize the importance of document naming conventions.', 'Review examples of correctly named technical files and upload an anonymised list of sample file names or a short note explaining the naming pattern.', 'Describes the naming logic used, including date, project code, version, or document type, and shows understanding of its role in document retrieval.'),
  ('documentation', 1, 1, 6, '1.1.6. To understand basic version control expectations.', 'Compare two versions of the same document and upload a redacted version label example, sample revision table, or short comparison note.', 'Correctly identifies the most recent version and explains how versioning or change labelling allows it to be recognized.'),
  ('documentation', 1, 1, 7, '1.1.7. To identify required information in a technical record.', 'Review a completed task log, checklist, or inspection form and upload a blank form, anonymised excerpt, or platform note listing its mandatory fields.', 'Identifies key fields such as date, task, responsible person, data, result, and notes.'),
  ('documentation', 1, 1, 8, '1.1.8. To recognize confidentiality or access rules for technical documents.', 'Review document access rules with the mentor and upload a short access- level note distinguishing between documents that can be viewed, edited, shared internally, or shared externally.', 'Correctly distinguishes between documents that can be edited, viewed only, or shared externally.'),
  ('documentation', 1, 1, 9, '1.1.9. To understand the role of documentation in task traceability.', 'Follow one documented task from instruction to completion and upload an anonymised traceability map or short log note showing instruction, role, action taken, and result.', 'Explains how documentation shows what was done, by whom, and with which result.'),
  ('documentation', 1, 1, 10, '1.1.10. To identify evidence suitable for app-based documentation.', 'Upload a short text note, photo, or screenshot showing one non- confidential example of documentation practice observed during the internship.', 'Uploaded evidence is relevant, clear, and linked to a real documentation practice observed in the workplace.'),
  ('documentation', 1, 2, 1, '1.2.1. To identify common types of technical documentation used in engineering work.', 'Review project materials and record in the platform at least five document types used by the team, such as drawings, logs, reports, specifications, or checklists.', 'Correctly identifies at least five relevant types of technical documentation used in engineering work.'),
  ('documentation', 1, 2, 2, '1.2.2. To recognize the function of technical drawings or diagrams.', 'Observe how engineers use a drawing, diagram, layout, flowchart, or schematic during a task and upload an anonymised diagram excerpt, simplified sketch, or explanatory note.', 'Explains what information the drawing or diagram provides to the project team.'),
  ('documentation', 1, 2, 3, '1.2.3. To identify the purpose of specifications and datasheets.', 'Review one technical specification, datasheet, or product sheet and upload a public datasheet, redacted excerpt, or summary table of key parameters.', 'Identifies key information such as parameters, limits, materials, components, or operating conditions.'),
  ('documentation', 1, 2, 4, '1.2.4. To recognize the role of task logs and daily records.', 'Review an example of a daily activity log, maintenance log, lab notebook, or project diary and upload a blank template, anonymised excerpt, or short platform note.', 'Explains how the log records completed tasks, observations, and follow-up actions.'),
  ('documentation', 1, 2, 5, '1.2.5. To identify test reports and measurement records.', 'Review one test record, measurement sheet, or result table and upload an anonymised measurement table, sample test record, or redacted result sheet.', 'Identifies the measured variable, unit of measurement, result, and reference value or acceptance range.'),
  ('documentation', 1, 2, 6, '1.2.6. To recognize quality control or inspection documents.', 'Observe a checklist, inspection form, validation record, or non-conformity report and upload a blank checklist, redacted form, or short note explaining its quality-control function.', 'Explains how the document supports quality control or verification of work.'),
  ('documentation', 1, 2, 7, '1.2.7. To identify safety-related documentation.', 'Locate and review one safety instruction, risk assessment, operating procedure, or warning label and upload a public safety instruction, blank risk- assessment form, generic label photo, or short note.', 'Identifies the safety purpose of the document and one required precaution.'),
  ('documentation', 1, 2, 8, '1.2.8. To recognize meeting minutes and action trackers as technical documentation.', 'Review technical meeting minutes or an action tracker and upload an anonymised tracker, redacted minutes excerpt, or platform note listing decisions, actions, responsible roles, and deadlines.', 'Identifies decisions, assigned actions, responsible persons or roles, and deadlines.'),
  ('documentation', 1, 2, 9, '1.2.9. To identify documentation used for change tracking.', 'Review a change log, revision table, issue tracker, or update note and upload a sample change log, redacted revision table, or short explanation of what changed, when, and why.', 'Explains what changed, when it changed, and why the change was recorded.'),
  ('documentation', 1, 2, 10, '1.2.10. To classify technical documents according to their project function.', 'Create an app-based classification note grouping observed documents by purpose: instruction, recording, verification, reporting, or handover.', 'Correctly classifies documents and gives one relevant non- confidential example for each selected category.'),
  ('documentation', 2, 1, 1, '2.1.1. To record assigned task steps in chronological order.', 'Complete a supervised digital project log describing the main steps followed during one assigned task in chronological order.', 'Log entries are complete, chronological, and understandable to another team member.'),
  ('documentation', 2, 1, 2, '2.1.2. To document technical results using clear and accurate data.', 'Record measurements, outputs, test results, or observations in the required digital format, including values, units, dates, and reference conditions.', 'Results include correct values, units, dates, and relevant reference conditions.'),
  ('documentation', 2, 1, 3, '2.1.3. To use standard logbook or reporting templates correctly.', 'Fill in a company logbook, digital form, or task record under mentor supervision and upload the completed blank/sample template or redacted form.', 'All mandatory fields are completed according to the template requirements.'),
  ('documentation', 2, 1, 4, '2.1.4. To distinguish between actions performed and results obtained.', 'Write one platform log entry structured into action performed, result obtained, and short comment or interpretation.', 'The entry clearly separates procedure, result, and short comment or interpretation.'),
  ('documentation', 2, 1, 5, '2.1.5. To record deviations, anomalies, or unexpected issues.', 'Add an anonymised deviation note or issue log entry describing the expected condition, observed deviation, and relevant context.', 'The deviation is described factually, with relevant context and without unsupported conclusions.'),
  ('documentation', 2, 1, 6, '2.1.6. To attach relevant evidence to support technical records.', 'Upload a non-confidential photo, screenshot, data extract, or short note and link it to the corresponding platform log entry.', 'Evidence is clear, relevant, properly labelled, and directly connected to the log entry.'),
  ('documentation', 2, 1, 7, '2.1.7. To apply basic technical terminology in documentation.', 'Write a short technical note using terminology provided by the mentor or project documents, including at least five relevant technical terms.', 'Technical terms are used correctly and consistently with workplace documentation.'),
  ('documentation', 2, 1, 8, '2.1.8. To update task status in a structured way.', 'Mark an assigned task as planned, in progress, completed, blocked, or requiring review in the platform, adding a short explanatory note.', 'Task status is accurate and supported by a short explanation or evidence.'),
  ('documentation', 2, 1, 9, '2.1.9. To record supervisor instructions and follow-up actions.', 'Add mentor feedback, corrections, or next steps to the project log after a review, including responsible role and expected follow-up deadline.', 'Follow-up actions are clearly recorded with responsible person or role and expected deadline.'),
  ('documentation', 2, 1, 10, '2.1.10. To revise technical records based on mentor feedback.', 'Edit one project log entry after mentor comments and upload a before/after excerpt or revision note showing the update.', 'The revised entry addresses the feedback and improves clarity, accuracy, or completeness.'),
  ('documentation', 2, 2, 1, '2.2.1. To maintain a daily record of internship activities.', 'Complete a daily platform log summarising tasks performed, tools or methods used, results observed, and short notes.', 'Daily log is submitted on time and includes tasks, tools, results, and short notes.'),
  ('documentation', 2, 2, 2, '2.2.2. To summarize completed work in a concise technical format.', 'Write a concise daily technical update structured into completed work, partial outputs, pending items, and next steps.', 'Entry is concise and clearly distinguishes completed work, incomplete tasks, and next steps.'),
  ('documentation', 2, 2, 3, '2.2.3. To connect daily activities to the assigned technical workflow.', 'Tag or label each daily activity in the platform according to the relevant workflow, process step, work package, or operational area.', 'Activities are correctly linked to the relevant workflow, process, or project area.'),
  ('documentation', 2, 2, 4, '2.2.4. To record tools, software, equipment, or methods used.', 'Add a daily log section listing tools, software, instruments, equipment, or methods used, with a short purpose for each item.', 'Record includes correct names and explains the purpose of each tool or method.'),
  ('documentation', 2, 2, 5, '2.2.5. To document observations using factual language.', 'Write one platform observation note structured into observed fact, context, and optional interpretation where appropriate.', 'Observation is factual, specific, and clearly separated from personal interpretation.'),
  ('documentation', 2, 2, 6, '2.2.6. To track open questions, uncertainties, or blockers.', 'Add unresolved questions, uncertainties, or blockers to the platform issue/question log, including context and requested follow-up.', 'Questions or blockers are specific and include enough context for the mentor to respond.'),
  ('documentation', 2, 2, 7, '2.2.7. To organize daily evidence in a consistent format.', 'Upload or reference daily supporting material such as photos, diagrams, screenshots, tables, or short notes, using consistent names and dates.', 'Evidence is consistently named, dated, and linked to the correct daily activity.'),
  ('documentation', 2, 2, 8, '2.2.8. To include safety, quality, or compliance notes when relevant.', 'Record any safety instruction, quality check, or compliance requirement encountered during the day in a short platform note.', 'Note correctly identifies the requirement and explains its relevance to the task.'),
  ('documentation', 2, 2, 9, '2.2.9. To produce a concise end-of-week summary from daily records.', 'Review daily logs and upload a weekly platform summary including completed activities, key findings, blockers, and next steps.', 'Weekly summary is coherent, concise, and accurately reflects the daily records.'),
  ('documentation', 2, 2, 10, '2.2.10. To use daily records to prepare for mentor review.', 'Select relevant daily entries and prepare a mentor-review note summarising progress, difficulties, and proposed next steps.', 'Intern uses records effectively to explain progress, difficulties, and planned follow-up actions.'),
  ('documentation', 3, 1, 1, '3.1.1. To prepare concise technical summaries of completed work.', 'Write and upload an anonymised technical summary describing the objective, completed activities, and main outputs of an assigned task.', 'Summary is concise, technically accurate, and includes objective, completed work, and outputs.'),
  ('documentation', 3, 1, 2, '3.1.2. To report progress against assigned tasks or project milestones.', 'Prepare a digital progress update structured into planned work, completed tasks, ongoing items, delays, and next actions.', 'Progress update clearly distinguishes completed work, pending items, delays, and next actions.'),
  ('documentation', 3, 1, 3, '3.1.3. To present technical results using appropriate data and units.', 'Include measured values, calculations, tables, or test outputs in a technical progress report and upload a redacted table, calculation extract, or result summary.', 'Data are accurate, properly labelled, and include correct units and reference conditions.'),
  ('documentation', 3, 1, 4, '3.1.4. To summarize technical issues or deviations objectively.', 'Write and upload an anonymised issue/deviation summary including observed condition, expected condition, context, and supporting note or extract.', 'Issue is described factually, with relevant context, evidence, and no unsupported assumptions.'),
  ('documentation', 3, 1, 5, '3.1.5. To explain methods or procedures followed during technical work.', 'Document the main steps, tools, software, equipment, or procedures used to complete a task and upload a method summary, anonymised procedure excerpt, or workflow note.', 'Procedure is described clearly enough for another team member to understand the workflow.'),
  ('documentation', 3, 1, 6, '3.1.6. To select relevant evidence to support technical reporting.', 'Attach or reference supporting evidence such as non-confidential images, redacted data tables, diagrams, or log excerpts within a report entry.', 'Evidence is relevant, correctly labelled, and directly supports the reported technical content.'),
  ('documentation', 3, 1, 7, '3.1.7. To identify limitations affecting technical results.', 'Add a limitations note to a technical summary or report, describing constraints, assumptions, missing data, boundary conditions, or uncertainty sources.', 'Limitations are clearly identified and linked to their possible impact on the reported outcome.'),
  ('documentation', 3, 1, 8, '3.1.8. To formulate practical next steps based on reported findings.', 'Conclude a progress report with an action list identifying follow-up checks, required decisions, responsible roles, or next technical steps.', 'Next steps are specific, realistic, and logically connected to the reported findings.'),
  ('documentation', 3, 1, 9, '3.1.9. To adapt the level of detail to the report audience.', 'Prepare one audience-adapted technical update, or two short versions of the same update showing different levels of technical detail.', 'Report uses an appropriate level of detail, terminology, and explanation for the intended audience.'),
  ('documentation', 3, 1, 10, '3.1.10. To revise a technical summary before submission.', 'Review and edit a technical summary before sharing it, uploading a revised version with tracked changes, a revision note, or a before/after comparison.', 'Final version is clear, complete, correctly formatted, and requires only minor corrections from the mentor.'),
  ('documentation', 3, 2, 1, '3.2.1. To structure a technical report according to workplace expectations.', 'Prepare and upload a structured report outline or redacted report draft including required sections such as objective, method, results, discussion, and conclusion.', 'Report follows the expected structure and includes all required sections.'),
  ('documentation', 3, 2, 2, '3.2.2. To define the scope and purpose of a technical report.', 'Write a report introduction or platform note defining purpose, context, scope, and boundaries of the technical activity.', 'Scope and purpose are clear, specific, and consistent with the assigned task.'),
  ('documentation', 3, 2, 3, '3.2.3. To organize technical information in a logical sequence.', 'Arrange report content from background and method to results, interpretation, and follow-up actions, uploading a section map, structured outline, or redacted report excerpt.', 'Information follows a logical order and can be understood without additional verbal explanation.'),
  ('documentation', 3, 2, 4, '3.2.4. To present technical information using suitable tables, figures, or diagrams.', 'Convert structured technical information into an anonymised table, diagram, flowchart, annotated image, or figure with clear labels and a short caption.', 'Visual element is readable, correctly labelled, and helps clarify the technical content of the report.'),
  ('documentation', 3, 2, 5, '3.2.5. To represent technical data using appropriate graphs.', 'Create and upload an anonymised technical graph based on non- confidential, redacted, or mentor- approved data, showing trends, comparisons, distributions, tolerances, or performance results.', 'Graph is technically correct, includes clear title, axes, units, and legend where needed, and supports interpretation of the data.'),
  ('documentation', 3, 2, 6, '3.2.6. To distinguish between data, interpretation, and recommendations.', 'Write and upload a redacted report section or platform note structured into data/results, interpretation, and recommended actions.', 'Report clearly separates observed data, analysis, and recommendations.'),
  ('documentation', 3, 2, 7, '3.2.7. To reference supporting documents and sources correctly.', 'Prepare a reference list, document index, or report excerpt citing supporting drawings, specifications, standards, manuals, datasets, or previous reports using generic or redacted identifiers where needed.', 'References are complete enough to allow the reader to locate the supporting documents.'),
  ('documentation', 3, 2, 8, '3.2.8. To ensure consistency of terminology, units, and abbreviations.', 'Review the report and upload a consistency checklist, edited excerpt, or terminology table showing checked terms, acronyms, symbols, and units.', 'Terminology, acronyms, symbols, and units are consistent throughout the report.'),
  ('documentation', 3, 2, 9, '3.2.9. To prepare a report that supports internal review or decision-making.', 'Draft and upload an anonymised review-ready report summary including findings, supporting evidence, open points, and required decisions.', 'Report enables the reviewer to understand the situation, evaluate the evidence, and identify required decisions.'),
  ('documentation', 3, 2, 10, '3.2.10. To submit a complete technical report with supporting annexes.', 'Compile and upload a complete report package with redacted or anonymised annexes, such as logs, images, calculations, tables, graphs, or data extracts.', 'Report package is complete, organized, and includes all required supporting materials.'),
  ('documentation', 4, 1, 1, '4.1.1. To prepare documentation that can be reused by other team members.', 'Create and upload a reusable technical note, guide, or procedure. Where the full document cannot be uploaded, provide an anonymised excerpt, structure outline, or sample section with mentor confirmation of completeness.', 'Document is clear, complete, technically accurate, and usable by another team member without additional explanation.'),
  ('documentation', 4, 1, 2, '4.1.2. To document technical workflows for future reference.', 'Create and upload a workflow map, flowchart, or process table showing steps, inputs, outputs, roles, and decision points. Where the real workflow is confidential, upload a redacted or simplified version.', 'Workflow is logically structured and accurately represents the real process followed by the team.'),
  ('documentation', 4, 1, 3, '4.1.3. To produce handover documentation for an ongoing activity.', 'Prepare and upload a handover note including current status, completed work, open issues, risks, and next actions. Where full content is sensitive, upload a redacted version or handover checklist with mentor confirmation.', 'Handover note enables another person to continue the activity with minimal loss of information.'),
  ('documentation', 4, 1, 4, '4.1.4. To consolidate project knowledge from multiple sources.', 'Combine information from logs, reports, meetings, datasets, drawings, or mentor feedback into a structured knowledge summary. Where source materials cannot be uploaded, provide a document index, synthesis table, or redacted summary with mentor confirmation.', 'Document integrates relevant sources coherently and avoids duplication, gaps, or contradictions.'),
  ('documentation', 4, 1, 5, '4.1.5. To document lessons learned from completed technical activities.', 'Prepare and upload a lessons learned record including successful practices, issues encountered, and proposed improvements, using anonymised cases where needed.', 'Lessons learned are specific, technically relevant, and linked to practical improvement actions.'),
  ('documentation', 4, 1, 6, '4.1.6. To standardize recurring documentation practices.', 'Propose and upload a template, checklist, or reporting structure for a recurring technical activity, using blank, anonymised, or simplified fields where needed.', 'Proposed structure is practical, easy to use, and aligned with workplace documentation needs.'),
  ('documentation', 4, 1, 7, '4.1.7. To make technical documentation understandable across disciplines.', 'Revise a technical document for cross- disciplinary clarity and upload a before/after excerpt, redacted excerpt, or reconstructed sample with mentor confirmation.', 'Document keeps technical accuracy while reducing unnecessary jargon and clarifying essential terms.'),
  ('documentation', 4, 1, 8, '4.1.8. To link documentation to supporting evidence and references.', 'Prepare and upload a reference list or evidence index linking the document to supporting data, drawings, calculations, standards, test records, or previous reports. Where files cannot be shared, use anonymised reference codes and mentor validation.', 'References are accurate, accessible, and allow future users to verify the documented information.'),
  ('documentation', 4, 1, 9, '4.1.9. To organize documentation for long-term storage and retrieval.', 'Save documents in the correct repository and upload a repository screenshot, folder- structure note, or file index showing naming, tagging, storage location, and version labels. Where screenshots expose sensitive information, upload a reconstructed example or mentor validation note.', 'Documents can be easily located, identified, and retrieved by other authorised users.'),
  ('documentation', 4, 1, 10, '4.1.10. To improve existing documentation based on user feedback.', 'Review an existing document with a mentor or colleague and upload a revised excerpt, feedback summary, before/after comparison, or change summary with mentor confirmation.', 'Revised document addresses feedback and shows measurable improvement in usability or accuracy.'),
  ('documentation', 4, 2, 1, '4.2.1. To apply traceability principles to technical documentation.', 'Prepare and upload a traceability table, matrix, or report excerpt linking requirements, activities, results, evidence, and conclusions. Where the full matrix is confidential, upload a redacted version or simplified traceability sample with mentor confirmation.', 'Document clearly shows the connection between initial requirements, performed work, evidence, and outcomes.'),
  ('documentation', 4, 2, 2, '4.2.2. To check documentation against quality requirements before submission.', 'Review a technical deliverable using a checklist and upload the completed quality checklist. Where the deliverable cannot be uploaded, provide the checklist, a redacted excerpt, or mentor confirmation of the checked document.', 'Deliverable meets all checklist requirements and is ready for supervisor or team review.'),
  ('documentation', 4, 2, 3, '4.2.3. To maintain version control in technical deliverables.', 'Update a document revision table or change log and upload a revision table, change log, or version-history excerpt showing version, date, change made, reason, and author/role. Where internal history cannot be shared, upload a redacted or sample record.', 'Revision history clearly records what changed, when, why, and by whom.'),
  ('documentation', 4, 2, 4, '4.2.4. To ensure consistency between technical documents and supporting data.', 'Cross-check reported values, tables, figures, calculations, or conclusions against source data and upload a cross- check table, verification note, or redacted comparison excerpt.', 'Reported information matches the source data and any discrepancies are corrected or explained.'),
  ('documentation', 4, 2, 5, '4.2.5. To identify gaps or inconsistencies in technical documentation.', 'Review a document package and upload a documentation review note or issue list identifying missing information, unclear sections, duplicated content, or inconsistent terminology.', 'Identified issues are relevant, clearly described, and linked to specific sections or documents.'),
  ('documentation', 4, 2, 6, '4.2.6. To prepare documentation suitable for audit or formal review.', 'Organize and upload an audit-ready or review-ready package including required records, approvals, evidence, and annexes. Where upload is not feasible due to file size, confidentiality, or platform limits, upload a package index, review checklist, sample excerpt, and mentor confirmation.', 'Package is complete, ordered, and allows an external reviewer to verify the documented work.'),
  ('documentation', 4, 2, 7, '4.2.7. To document technical decisions and their rationale.', 'Write and upload a technical decision record including selected option, alternatives considered, supporting evidence, and reasons for rejection. Where alternatives or evidence are confidential, upload a redacted decision record or decision-summary template with mentor confirmation.', 'Decision record is evidence-based and clearly explains why the selected option was adopted.'),
  ('documentation', 4, 2, 8, '4.2.8. To ensure compliance with applicable documentation rules.', 'Check a technical document against relevant procedures, project requirements, standards, or instructions and upload a compliance check note or completed review checklist. Where rules are internal or client-specific, use generic references or mentor-confirmed checklist items.', 'Document complies with applicable rules, or deviations are clearly identified and justified.'),
  ('documentation', 4, 2, 9, '4.2.9. To validate final documentation with relevant stakeholders.', 'Submit a technical deliverable for review and upload a platform validation entry, mentor/supervisor approval note, sign-off record, anonymised validation record, or mentor confirmation note.', 'Deliverable receives approval or requires only minor corrections before acceptance.'),
  ('documentation', 4, 2, 10, '4.2.10. To recommend improvements to documentation quality processes.', 'Propose and upload one improvement to the team’s documentation workflow, template, review process, or evidence collection method, describing the issue, suggested improvement, expected benefit, and implementation conditions.', 'Recommendation is practical, justified by observed needs, and supports better quality, traceability, or efficiency.')
) AS v(code, level, kpi_index, triplet_index, objective, task, criterion)
JOIN competencies c ON c.code = v.code
JOIN competency_kpis k ON k.competency_id = c.id
  AND k.level = v.level AND k.kpi_index = v.kpi_index
ON CONFLICT (kpi_id, triplet_index) DO UPDATE SET
  objective = EXCLUDED.objective,
  task = EXCLUDED.task,
  criterion = EXCLUDED.criterion;
